// Improved application with security best practices
// This version includes proper error handling, input validation, and security measures

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const cors = require('cors');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers - protects against well-known web vulnerabilities
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
}));

// CORS configuration - restrict to allowed origins only
const corsOptions = {
  origin: function (origin, callback) {
    // Allow requests with no origin (like mobile apps or curl requests)
    // In production, replace with your allowed origins
    const allowedOrigins = process.env.ALLOWED_ORIGINS 
      ? process.env.ALLOWED_ORIGINS.split(',') 
      : ['http://localhost:3000'];

    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
};
app.use(cors(corsOptions));

// Rate limiting - prevents brute force and DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  handler: function (req, res, next) {
    res.status(429).json({
      error: 'Too many requests',
      message: 'Too many requests from this IP, please try again later.',
      retryAfter: Math.round(req.rateLimit.resetTime / 1000)
    });
  }
});
app.use(limiter);

// Stricter rate limiting for sensitive endpoints
const sensitiveLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: { error: 'Too many attempts, please try again later.' }
});

// Request logging - keeps audit trail
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// Body parsing with size limits
app.use(express.json({ 
  limit: '10kb', // Prevent large payload attacks
  strict: true 
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

// Validate pagination and query parameters
const validateQueryParams = [
  expressValidator.query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  expressValidator.query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  expressValidator.query('sort')
    .optional()
    .isIn(['id', 'name', 'email', '-id', '-name', '-email'])
    .withMessage('Invalid sort field'),
  (req, res, next) => {
    const errors = expressValidator.validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }
    next();
  }
];

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// Custom error class for application errors
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
    Error.captureStackTrace(this, this.constructor);
  }
}

// Async handler wrapper to catch async errors
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// 404 handler
app.use((req, res, next) => {
  next(new AppError(`Route ${req.method} ${req.path} not found`, 404));
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (in production, use proper logging service)
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  // Handle operational errors differently from programming errors
  if (err.isOperational) {
    return res.status(err.statusCode).json({
      error: err.message,
      ...(isDevelopment && { stack: err.stack })
    });
  }

  // Handle specific error types
  if (err.type === 'entity.parse.failed') {
    return res.status(400).json({
      error: 'Invalid JSON format'
    });
  }

  if (err.code === 'LIMIT_FILE_SIZE') {
    return res.status(413).json({
      error: 'File size exceeds limit'
    });
  }

  // Default error response
  const statusCode = err.statusCode || 500;
  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// ============================================================================
// ROUTES WITH VALIDATION AND ERROR HANDLING
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    next(new AppError('Health check failed', 500));
  }
});

// Users endpoint with validation
app.get('/users', validateQueryParams, asyncHandler(async (req, res, next) => {
  try {
    const { limit = 10, offset = 0, sort = 'id' } = req.query;

    // Validate input ranges have been applied by middleware
    const safeLimit = Math.min(Math.max(limit, 1), 100);
    const safeOffset = Math.max(offset, 0);

    // Mock data - in real app, this would be a database query
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    // Apply sorting with validation
    const [sortField, sortDir] = sort.startsWith('-') 
      ? [sort.slice(1), -1] 
      : [sort, 1];

    const validSortFields = ['id', 'name', 'email'];
    if (!validSortFields.includes(sortField)) {
      throw new AppError('Invalid sort field', 400);
    }

    const sortedUsers = [...allUsers].sort((a, b) => {
      if (a[sortField] < b[sortField]) return -1 * sortDir;
      if (a[sortField] > b[sortField]) return 1 * sortDir;
      return 0;
    });

    // Apply pagination
    const paginatedUsers = sortedUsers.slice(safeOffset, safeOffset + safeLimit);

    // Return response with metadata
    res.json({
      data: paginatedUsers,
      meta: {
        total: allUsers.length,
        limit: safeLimit,
        offset: safeOffset,
        hasMore: safeOffset + safeLimit < allUsers.length
      }
    });
  } catch (error) {
    next(error);
  }
}));

// Example of a user creation endpoint with full validation
app.post('/users', [
  expressValidator.body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z0-9\s\-']+$/)
    .withMessage('Name contains invalid characters')
    .escape(),
  expressValidator.body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: 255 })
    .withMessage('Email too long'),
  (req, res, next) => {
    const errors = expressValidator.validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }
    next();
  }
], asyncHandler(async (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Additional business logic validation
    // In real app, check for duplicates in database

    // Simulate user creation
    const newUser = {
      id: Date.now(), // In real app, let database generate ID
      name: name,
      email: email,
      createdAt: new Date().toISOString()
    };

    // Return 201 Created with location header
    res.status(201)
       .location(`/users/${newUser.id}`)
       .json({
         data: newUser,
         message: 'User created successfully'
       });
  } catch (error) {
    next(error);
  }
}));

// Single user endpoint with ID validation
app.get('/users/:id', [
  expressValidator.param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .toInt(),
  (req, res, next) => {
    const errors = expressValidator.validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }
    next();
  }
], asyncHandler(async (req, res, next) => {
  try {
    const { id } = req.params;

    // Mock data lookup
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      { id: 4, name: 'Diana', email: 'diana@example.com' },
      { id: 5, name: 'Eve', email: 'eve@example.com' },
    ];

    const user = allUsers.find(u => u.id === id);

    if (!user) {
      throw new AppError('User not found', 404);
    }

    res.json({ data: user });
  } catch (error) {
    next(error);
  }
}));

// ============================================================================
// SERVER STARTUP WITH ERROR HANDLING
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`Time: ${new Date().toISOString()}`);
});

// Graceful shutdown handling
const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  server.close((err) => {
    if (err) {
      console.error('Error during server shutdown:', err);
      process.exit(1);
    }
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);
};

// Handle shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to exit here
  // process.exit(1);
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  // Close server gracefully before exiting
  server.close(() => {
    process.exit(1);
  });
});

module.exports = { app, server };

# Security Review: app.js

## Executive Summary

The original `app.js` file has several security vulnerabilities and lacks proper error handling and input validation. Below are the identified issues and recommendations for improvement.

---

## 🔴 Critical Issues Found

### 1. No Security Headers
**Issue**: Application lacks HTTP security headers
**Risk**: Vulnerable to XSS, clickjacking, and other injection attacks
**Fix**: Implement Helmet.js middleware

### 2. No Rate Limiting
**Issue**: No protection against excessive requests
**Risk**: DoS attacks, brute force attempts, resource exhaustion
**Fix**: Implement express-rate-limit

### 3. No CORS Configuration
**Issue**: No origin restrictions
**Risk**: Cross-origin attacks, data theft
**Fix**: Configure CORS with whitelisted origins

### 4. No Input Validation
**Issue**: All inputs are trusted without validation
**Risk**: Injection attacks, data corruption
**Fix**: Implement express-validator for all inputs

### 5. No Error Handling Strategy
**Issue**: No centralized error handling
**Risk**: Information leakage, inconsistent responses
**Fix**: Implement global error handler

### 6. No Request Size Limits
**Issue**: No limits on request body size
**Risk**: Memory exhaustion, DoS
**Fix**: Add size limits to body parsers

### 7. No Logging/Audit Trail
**Issue**: No request logging
**Risk**: Inability to detect attacks, compliance issues
**Fix**: Implement Morgan for logging

### 8. No Graceful Shutdown
**Issue**: Server shuts down abruptly
**Risk**: Data loss, incomplete transactions
**Fix**: Implement graceful shutdown handlers

---

## ✅ Detailed Security Improvements

### 1. Security Headers (Helmet)

```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      // ... additional directives
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));
```

**Headers Added:**
- `X-Content-Type-Options: nosniff`
- `X-Frame-Options: DENY`
- `X-XSS-Protection: 1; mode=block`
- `Strict-Transport-Security`
- `Content-Security-Policy`

---

### 2. CORS Configuration

```javascript
const cors = require('cors');

const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [];
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
};

app.use(cors(corsOptions));
```

---

### 3. Rate Limiting

```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per window
  message: 'Too many requests from this IP'
});

// Stricter for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per window
  message: 'Too many authentication attempts'
});
```

---

### 4. Input Validation

```javascript
const { body, param, query, validationResult } = require('express-validator');

// Example: Validate user creation
app.post('/users', [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .matches(/^[a-zA-Z0-9\s\-']+$/)
    .escape(),
  body('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .isLength({ max: 255 }),
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }
    next();
  }
], handler);
```

**Validation Types:**
- **Path Parameters**: IDs, slugs
- **Query Parameters**: Pagination, filters, sorting
- **Request Body**: User input data
- **Headers**: Authorization tokens

---

### 5. Error Handling

```javascript
// Custom error class
class AppError extends Error {
  constructor(message, statusCode = 500, isOperational = true) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.timestamp = new Date().toISOString();
  }
}

// Async handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Global error handler
app.use((err, req, res, next) => {
  // Log error
  console.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

  // Don't leak stack traces in production
  const isDevelopment = process.env.NODE_ENV !== 'production';

  res.status(err.statusCode || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack })
  });
});
```

---

### 6. Request Size Limits

```javascript
app.use(express.json({ 
  limit: '10kb'  // Prevent large payload attacks
}));

app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));
```

---

### 7. Logging

```javascript
const morgan = require('morgan');

// Log format: combined includes IP, user-agent, etc.
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// Or use custom format
app.use(morgan(':method :url :status :response-time ms - :res[content-length]'));
```

---

### 8. Graceful Shutdown

```javascript
process.on('SIGTERM', () => {
  console.log('SIGTERM received');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  // Cleanup and exit
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  server.close(() => process.exit(1));
});
```

---

## 📋 Additional Security Recommendations

### Environment Variables

Create a `.env` file (add to `.gitignore`):

```env
NODE_ENV=production
PORT=3000
ALLOWED_ORIGINS=https://yourdomain.com,https://api.yourdomain.com
DATABASE_URL=postgresql://...
JWT_SECRET=your-secret-key
LOG_LEVEL=info
```

### Additional NPM Packages to Install

```bash
npm install helmet express-rate-limit express-validator cors morgan
npm install --save-dev dotenv
```

### HTTPS in Production

Always use HTTPS in production. Use:
- Let's Encrypt (free SSL certificates)
- Cloudflare SSL
- AWS ACM / other cloud provider certificates

```javascript
// Force HTTPS in production
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure) {
      return res.redirect('https://' + req.headers.host + req.url);
    }
    next();
  });
}
```

### Authentication & Authorization

Consider adding:
- JWT or session-based authentication
- Role-based access control (RBAC)
- API keys for external integrations

```javascript
// Example: Authentication middleware
const authenticate = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};
```

### Database Security

If adding database operations:
- Use parameterized queries (prevent SQL injection)
- Implement row-level security
- Use connection pooling with proper limits
- Encrypt sensitive data at rest

### API Documentation

Use OpenAPI/Swagger for documenting API security:

```javascript
const swaggerUi = require('swagger-ui-express');
const swaggerDocument = require('./swagger.json');

app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerDocument));
```

### Monitoring & Alerting

Implement:
- Health check endpoints
- Performance monitoring (APM tools)
- Error tracking (Sentry, Rollbar)
- Log aggregation (ELK stack, Datadog)

---

## 🔍 Security Checklist

Use this checklist to verify security measures:

- [ ] Security headers implemented (Helmet)
- [ ] CORS properly configured
- [ ] Rate limiting implemented
- [ ] Input validation on all endpoints
- [ ] Output encoding/sanitization
- [ ] Centralized error handling
- [ ] Request size limits
- [ ] Logging implementation
- [ ] HTTPS enforced in production
- [ ] Environment variables for secrets
- [ ] Dependencies regularly updated
- [ ] Graceful shutdown handling
- [ ] API documentation with security notes
- [ ] Authentication/authorization (if needed)
- [ ] Security headers tested
- [ ] Input fuzzing testing
- [ ] Regular security audits

---

## 📚 Additional Resources

- [OWASP Top 10](https://owasp.org/www-project-top-ten/)
- [Node.js Security Best Practices](https://nodejs.org/en/docs/guides/security/)
- [Helmet.js Documentation](https://helmetjs.github.io/)
- [Express.js Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)

---

## 🔄 migration Steps

1. Install required packages
2. Set up environment variables
3. Add security middleware first (before routes)
4. Implement error handling middleware
5. Add validation to each endpoint
6. Update tests
7. Deploy to staging environment
8. Perform security testing
9. Deploy to production
10. Monitor and adjust

---

