#!/usr/bin/env node

/**
 * Credential Verification Script
 * 
 * This script checks if the credentials in .env.test are real/valid.
 * For security purposes, we EXPECT all of these to FAIL validation.
 * 
 * If any credentials succeed in connecting/authenticating, that's a
 * CRITICAL SECURITY ISSUE - it means real credentials were accidentally
 * committed to the repository.
 */

const dotenv = require('dotenv');
const { Pool } = require('pg');
const https = require('https');

// Load environment variables
dotenv.config({ path: '.env.test' });

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  gray: '\x1b[90m'
};

function log(level, message) {
  const timestamp = new Date().toISOString();
  const color = level === 'PASS' ? colors.green :
                level === 'FAIL' ? colors.red :
                level === 'WARN' ? colors.yellow :
                level === 'INFO' ? colors.blue : colors.reset;

  console.log(`${color}[${level}]${colors.reset} ${timestamp} - ${message}`);
}

function logSection(title) {
  console.log(`\n${'='.repeat(60)}`);
  console.log(`${title}`);
  console.log(`${'='.repeat(60)}\n`);
}

// ============================================================================
// DATABASE CREDENTIAL CHECK
// ============================================================================

async function checkDatabaseConnection() {
  logSection('CHECKING DATABASE CREDENTIALS');

  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    log('INFO', 'DATABASE_URL not set - skipping database check');
    return { checked: false, reason: 'not_set' };
  }

  log('INFO', `DATABASE_URL found: ${maskConnectionString(dbUrl)}`);

  const pool = new Pool({
    connectionString: dbUrl,
    connectionTimeoutMillis: 5000, // 5 second timeout
  });

  try {
    log('INFO', 'Attempting database connection with 5 second timeout...');

    const client = await pool.connect();

    // CRITICAL SECURITY ISSUE: Connection succeeded!
    const result = await client.query('SELECT version()');
    await client.release();
    await pool.end();

    console.log(`\n${colors.red}${'='.repeat(60)}`);
    console.log(`🚨 CRITICAL SECURITY ISSUE DETECTED 🚨`);
    console.log(`${'='.repeat(60)}${colors.reset}`);
    console.log('Database connection SUCCESSFUL - these are REAL credentials!');
    console.log('\nIMMEDIATE ACTION REQUIRED:');
    console.log('1. Rotate/change the database password immediately');
    console.log('2. Remove these credentials from the repository');
    console.log('3. Treat this database as potentially compromised');
    console.log('4. Review database access logs\n');

    return { 
      checked: true, 
      valid: true, 
      securityIssue: true,
      version: result.rows[0].version 
    };

  } catch (error) {
    await pool.end().catch(() => {});

    // Check if it's specifically an authentication error
    if (error.message.includes('authentication failed') || 
        error.message.includes('password authentication failed')) {
      log('PASS', 'Credentials failed authentication - expected (GOOD)');
      return { checked: true, valid: false, reason: 'auth_failed' };
    }

    // Check for connection/host errors (also good - means fake credentials)
    if (error.message.includes('connect') || 
        error.message.includes('ENOTFOUND') ||
        error.message.includes('ECONNREFUSED')) {
      log('PASS', `Connection failed: ${error.message.split('\n')[0]} - expected (GOOD)`);
      return { checked: true, valid: false, reason: 'connection_failed' };
    }

    // Other errors - also acceptable means credentials don't work
    log('PASS', `Credentials rejected: ${error.message.split('\n')[0]}`);
    return { checked: true, valid: false, reason: error.message };

  }
}

