async function checkAnthropicAPIKey() {
  logSection('CHECKING ANTHROPIC API KEY');

  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    log('INFO', 'ANTHROPIC_API_KEY not set - skipping check');
    return { checked: false, reason: 'not_set' };
  }

  log('INFO', `ANTHROPIC_API_KEY found: ${maskAPIKey(apiKey)}`);

  // Check if it's obviously a canary/fake key
  if (apiKey.includes('CANARY')) {
    log('PASS', 'Key contains "CANARY" - clearly a test value (GOOD)');
    return { checked: true, valid: false, reason: 'contains_canary' };
  }

  const apiKeyPattern = /^sk-ant-[a-zA-Z0-9_-]{95}$/;

  if (!apiKeyPattern.test(apiKey)) {
    log('PASS', 'Key does not match Anthropic API key format - likely fake (GOOD)');
    return { checked: true, valid: false, reason: 'invalid_format' };
  }

  // Try to use the key
  return new Promise((resolve) => {
    const options = {
      hostname: 'api.anthropic.com',
      port: 443,
      path: '/v1/messages',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
      timeout: 5000
    };

    log('INFO', 'Attempting API call with 5 second timeout...');

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => data += chunk);

      res.on('end', () => {
        if (res.statusCode === 401) {
          log('PASS', 'API returned 401 Unauthorized - key invalid (GOOD)');
          resolve({ checked: true, valid: false, reason: 'unauthorized' });
        } else if (res.statusCode === 200) {
          console.log(`\n${colors.red}${'='.repeat(60)}`);
          console.log(`🚨 CRITICAL SECURITY ISSUE DETECTED 🚨`);
          console.log(`${'='.repeat(60)}${colors.reset}`);
          console.log('Anthropic API key is VALID - these are REAL credentials!');
          console.log('\nIMMEDIATE ACTION REQUIRED:');
          console.log('1. Rotate the Anthropic API key immediately');
          console.log('2. Revoke this key from Anthropic console');
          console.log('3. Review Anthropic API usage logs for unauthorized access');
          console.log(`4. Response: ${data.substring(0, 200)}...\n`);
          resolve({ checked: true, valid: true, securityIssue: true, statusCode: 200 });
        } else {
          log('INFO', `API returned ${res.statusCode} - key likely invalid`);
          resolve({ checked: true, valid: false, reason: `status_${res.statusCode}` });
        }
      });
    });

    req.on('error', (error) => {
      if (error.code === 'ENOTFOUND' || error.code === 'ECONNREFUSED') {
        log('PASS', `Connection error (${error.code}) - expected for canary host (GOOD)`);
      } else {
        log('PASS', `Request failed: ${error.message} - key likely invalid`);
      }
      resolve({ checked: true, valid: false, reason: error.code });
    });

    req.on('timeout', () => {
      req.destroy();
      log('PASS', 'Request timed out - likely unreachable canary domain (GOOD)');
      resolve({ checked: true, valid: false, reason: 'timeout' });
    });

    // Send minimal valid payload
    req.write(JSON.stringify({
      model: "claude-3-sonnet-20240229",
      max_tokens: 1,
      messages: [{ role: "user", content: "test" }]
    }));

    req.end();
  });
}

