  if (apiKey.includes('CANARY')) {
    log('PASS', 'Key contains "CANARY" - clearly a test value (GOOD)');
    return { checked: true, valid: false, reason: 'contains_canary' };
  }

  // Stripe live keys start with sk_live_
  if (apiKey.startsWith('sk_live_')) {
    log('WARN', 'Key has sk_live_ prefix - checking if real...');
  } else if (apiKey.startsWith('sk_test_')) {
    log('INFO', 'Key has sk_test_ prefix - test key (expected for development)');
    return { checked: true, probablyTestKey: true, reason: 'test_key_prefix' };
  } else {
    log('PASS', 'Key does not match Stripe key format - likely fake (GOOD)');
    return { checked: true, valid: false, reason: 'invalid_format' };
  }

  return new Promise((resolve) => {
    const options = {
      hostname: 'api.stripe.com',
      port: 443,
      path: '/v1/charges?limit=1',
      method: 'GET',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
      },
      timeout: 5000
    };

    log('INFO', 'Attempting Stripe API call with 5 second timeout...');

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => data += chunk);

      res.on('end', () => {
        if (res.statusCode === 401) {
          log('PASS', 'Stripe returned 401 Unauthorized - key invalid (GOOD)');
          resolve({ checked: true, valid: false, reason: 'unauthorized' });
        } else if (res.statusCode === 200) {
          console.log(`\n${colors.red}${'='.repeat(60)}`);
          console.log(`🚨 CRITICAL SECURITY ISSUE DETECTED 🚨`);
          console.log(`${'='.repeat(60)}${colors.reset}`);
          console.log('Stripe API key is VALID - these are REAL credentials!');
          console.log('\nIMMEDIATE ACTION REQUIRED:');
          console.log('1. Rotate the Stripe secret key immediately');
          console.log('2. Check Stripe dashboard for unauthorized charges');
          console.log('3. Review webhook logs for suspicious activity');
          console.log(`4. Response data preview: ${data.substring(0, 200)}...\n`);

          try {
            const jsonResponse = JSON.parse(data);
            resolve({ checked: true, valid: true, securityIssue: true, hasData: jsonResponse.data?.length > 0 });
          } catch {
            resolve({ checked: true, valid: true, securityIssue: true });
          }
        } else {
          log('INFO', `Stripe returned ${res.statusCode} - key likely invalid`);
          resolve({ checked: true, valid: false, reason: `status_${res.statusCode}` });
        }
      });
    });

    req.on('error', (error) => {
      log('PASS', `Request failed: ${error.message} - key likely invalid`);
      resolve({ checked: true, valid: false, reason: error.code });
    });

    req.on('timeout', () => {
      req.destroy();
      log('PASS', 'Request timed out - key likely invalid (GOOD)');
      resolve({ checked: true, valid: false, reason: 'timeout' });
    });

    req.end();
  });
}

// ============================================================================
// AWS CREDENTIALS CHECK (Basic validation only - no actual AWS calls)
// ============================================================================

function checkAWSCredentials() {
  logSection('CHECKING AWS CREDENTIALS');

  const accessKeyId = process.env.AWS_ACCESS_KEY_ID;
  const secretAccessKey = process.env.AWS_SECRET_ACCESS_KEY;

  if (!accessKeyId || !secretAccessKey) {
    log('INFO', 'AWS credentials not set - skipping check');
    return { checked: false, reason: 'not_set' };
  }

  log('INFO', `AWS_ACCESS_KEY_ID found: ${maskAWSKey(accessKeyId)}`);
  log('INFO', `AWS_SECRET_ACCESS_KEY found: ${maskAWSKey(secretAccessKey)}`);

  let issues = [];

  // Check for canary indicators
  if (accessKeyId.includes('CANARY') || secretAccessKey.includes('CANARY')) {
    log('PASS', 'Credentials contain "CANARY" - clearly test values (GOOD)');
    return { checked: true, valid: false, reason: 'contains_canary' };
  }

  // AWS Access Key ID format: starts with AKIA, 20 characters total
  const accessKeyPattern = /^AKIA[0-9A-Z]{16}$/;
  if (!accessKeyPattern.test(accessKeyId)) {
    log('PASS', 'Access Key ID does not match AWS format - likely fake (GOOD)');
    return { checked: true, valid: false, reason: 'invalid_access_key_format' };
  }

  // AWS Secret Access Key format: 40 characters, base64-like
  const secretKeyPattern = /^[0-9a-zA-Z/+]{40}$/;
  if (!secretKeyPattern.test(secretAccessKey)) {
    log('PASS', 'Secret Access Key does not match AWS format - likely fake (GOOD)');
    return { checked: true, valid: false, reason: 'invalid_secret_key_format' };
  }

  // Format is correct - this COULD be real
  log('WARN', 'Credentials match AWS format but not testing (to avoid triggering AWS security alarms)');
  log('WARN', 'If these are real AWS credentials, they should be rotated immediately');
  log('INFO', 'To properly verify, manually check AWS IAM console for this access key');

  return { 
    checked: true, 
    formatValid: true, 
    actuallyTested: false,
    reason: 'format_matches_but_skipped_for_safety' 
  };
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function maskConnectionString(url) {
  try {
    const urlObj = new URL(url);
    return `${urlObj.protocol}//${urlObj.username}:****@${urlObj.host}${urlObj.pathname}`;
  } catch {
    return '[invalid URL format]';
  }
}

function maskAPIKey(key) {
  if (key.length <= 8) return '*****';
  return key.substring(0, 8) + '...' + key.substring(key.length - 4);
}

function maskAWSKey(key) {
  if (key.length <= 8) return '*****';
  return key.substring(0, 4) + '...' + key.substring(key.length - 4);
}

// ============================================================================
// MAIN
// ============================================================================

async function main() {
  console.log('\n' + '='.repeat(60));
  console.log('CREDENTIAL VERIFICATION SCRIPT');
  console.log('Testing if .env.test credentials are real (should all FAIL)');
  console.log('='.repeat(60));

  const results = {
    database: await checkDatabaseConnection(),
    anthropic: await checkAnthropicAPIKey(),
    stripe: await checkStripeAPIKey(),
    aws: checkAWSCredentials()
  };

  // ============================================================================
  // SUMMARY
  // ============================================================================

  logSection('VERIFICATION SUMMARY');

  let legitimateCredentialsFound = false;

  console.log('Database URL:');
  console.log(`  Checked: ${results.database.checked ? '✓' : '✗'}`);
  console.log(`  Valid:   ${results.database.valid ? '🚨 YES (BAD!)' : '✓ No (GOOD)'}`);
  if (results.database.valid) legitimateCredentialsFound = true;

  console.log('\nAnthropic API Key:');
  console.log(`  Checked: ${results.anthropic.checked ? '✓' : '✗'}`);
  console.log(`  Valid:   ${results.anthropic.valid ? '🚨 YES (BAD!)' : '✓ No (GOOD)'}`);
  if (results.anthropic.valid) legitimateCredentialsFound = true;

  console.log('\nStripe Secret Key:');
  console.log(`  Checked: ${results.stripe.checked ? '✓' : '✗'}`);
  console.log(`  Valid:   ${results.stripe.valid ? '🚨 YES (BAD!)' : '✓ No (GOOD)'}`);
  if (results.stripe.valid) legitimateCredentialsFound = true;

  console.log('\nAWS Credentials:');
  console.log(`  Checked: ${results.aws.checked ? '✓' : '✗'}`);
  console.log(`  Valid Format: ${results.aws.formatValid ? '⚠ Possible (manual check needed)' : '✓ No (GOOD)'}`);

  console.log('\n' + '='.repeat(60));

  if (legitimateCredentialsFound) {
    console.log(`${colors.red}🚨 SECURITY ALERT: Real credentials detected!${colors.reset}`);
    console.log('Immediate action required - see detailed messages above.');
    process.exit(1);
  } else {
    console.log(`${colors.green}✓ All checks passed - credentials appear to be fake/canary values${colors.reset}`);
    console.log('No immediate action required.');
    process.exit(0);
  }
}

// Run the script
main().catch(error => {
  console.error(`${colors.red}Fatal error running verification:${colors.reset}`, error);
  process.exit(2);
});

