#!/usr/bin/env node

/**
 * Credential Verification Script (No External Dependencies Version)
 * 
 * This script checks if the credentials in .env.test are real/valid.
 * For security purposes, we EXPECT all of these to FAIL validation.
 * 
 * No npm installation required - uses only Node.js built-in modules.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');

// ============ Load .env.test manually ============

function loadEnvFile(filePath) {
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    const lines = content.split('\n');
    const env = {};

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const [key, ...valueParts] = trimmed.split('=');
        if (key && valueParts.length > 0) {
          env[key.trim()] = valueParts.join('=').trim();
        }
      }
    }

    return env;
  } catch (error) {
    return {};
  }
}

// Load environment variables from .env.test
const env = loadEnvFile('.env.test');
Object.assign(process.env, env);

// ============ Colors and Logging ============

const colors = {
  reset: '\x1b[0m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  blue: '\x1b[34m',
  cyan: '\x1b[36m',
  gray: '\x1b[90m'
};

function log(level, message) {
  const timestamp = new Date().toISOString();
  const color = level === 'PASS' ? colors.green :
                level === 'FAIL' ? colors.red :
                level === 'WARN' ? colors.yellow :
                level === 'INFO' ? colors.blue : colors.reset;

  console.log(`${color}[${level}]${colors.reset} ${timestamp} - ${message}`);
}

function logSection(title) {
  console.log(`\n${colors.cyan}${'='.repeat(60)}`);
  console.log(`${title}`);
  console.log(`${'='.repeat(60)}${colors.reset}\n`);
}

// ============ Database Check (Basic validation only) ============

function checkDatabaseConnection() {
  logSection('CHECKING DATABASE CREDENTIALS');

  const dbUrl = process.env.DATABASE_URL;

  if (!dbUrl) {
    log('INFO', 'DATABASE_URL not set - skipping database check');
    return { checked: false, reason: 'not_set' };
  }

  log('INFO', `DATABASE_URL found: ${maskConnectionString(dbUrl)}`);

  // Parse the connection string
  try {
    const url = new URL(dbUrl);

    // Check for canary indicators in the URL
    const canaryIndicators = ['CANARY', 'internal', 'fake', 'test.local', 'db.internal'];
    const isCanary = canaryIndicators.some(indicator => 
      dbUrl.toUpperCase().includes(indicator.toUpperCase())
    );

    if (isCanary) {
      log('PASS', 'Connection string contains canary/test indicators (GOOD)');
      log('INFO', `  - Hostname: ${url.hostname}`);
      return { checked: true, valid: false, reason: 'canary_indicators' };
    }

    // Check if it's localhost/internal (likely fake for testing)
    if (url.hostname === 'localhost' || url.hostname.startsWith('192.168.') || 
        url.hostname.startsWith('10.') || url.hostname.includes('internal')) {
      log('INFO', 'Hostname suggests internal/private network');
      log('INFO', `  - Hostname: ${url.hostname}`);
      log('INFO', `  - Database: ${url.pathname.substring(1) || 'default'}`);
      return { checked: true, valid: false, reason: 'internal_hostname' };
    }

    // If it passes these checks, it MIGHT be real - warn the user
    console.log(`${colors.yellow}⚠️  WARNING: Database URL format looks legitimate${colors.reset}`);
    log('INFO', `  - Hostname: ${url.hostname}`);
    log('INFO', `  - Database: ${url.pathname.substring(1) || 'default'}`);
    log('INFO', `  - User: ${url.username}`);
    log('WARN', 'Could not verify without pg module. Manual check recommended.');

    return { checked: true, cannotVerify: true, reason: 'needs_manual_verification' };

  } catch (error) {
