const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const cors = require('cors');

const app = express();

// ===== SECURITY MIDDLEWARE =====

// Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },
  // Hide Express server info
  hidePoweredBy: true
}));

// CORS configuration - whitelist specific origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));

// Rate limiting - prevent DoS attacks
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 20,
  message: { error: 'Too many attempts, please try again later.' },
});

app.use(generalLimiter);

// Request size limits to prevent payload overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ===== HELPER FUNCTIONS =====

// Validation middleware helper
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path,
        message: err.msg,
        value: err.value // Help debugging without exposing too much
      }))
    });
  }
  next();
};

// Safe response helper
const safeResponse = (res, data, status = 200) => {
  res.status(status).json(data);
};

// Safe error response helper
const safeErrorResponse = (res, message = 'Internal server error', status = 500) => {
  const isDevelopment = process.env.NODE_ENV === 'development';
  res.status(status).json({
    error: message,
    ...(isDevelopment && { timestamp: new Date().toISOString() })
  });
};

// ===== LOGGING MIDDLEWARE =====
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    // Sanitize query params for logging (remove sensitive data)
    const sanitizedQuery = { ...req.query };
    delete sanitizedQuery.password;
    delete sanitizedQuery.token;
    delete sanitizedQuery.apiKey;

    console.log(`${req.method} ${req.path} ${res.statusCode} - ${duration}ms`, {
      ip: req.ip,
      query: Object.keys(sanitizedQuery).length > 0 ? sanitizedQuery : undefined
    });
  });
  next();
});

// ===== ROUTES =====

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    safeResponse(res, { 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development'
    });
  } catch (error) {
    console.error('Health check error:', error);
    safeErrorResponse(res, 'Health check failed');
  }
});

// Users endpoint with comprehensive validation
app.get('/users',
  [
    // Validate and sanitize query parameters
    query('limit')
      .optional()
      .trim()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .trim()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .trim()
      .escape() // Prevent XSS
      .isIn(['id', 'name', 'email'])
      .withMessage('Sort must be one of: id, name, email'),
    query('order')
      .optional()
      .trim()
      .toLowerCase()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be either asc or desc'),
    query('search')
      .optional()
      .trim()
      .escape() // Prevent XSS and injection
      .isLength({ max: 100 })
      .withMessage('Search term too long (max 100 characters)')
  ],
  validate,
  (req, res) => {
    try {
      const { limit = 10, offset = 0, sort = 'id', order = 'asc', search } = req.query;

      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
        { id: 3, name: 'Charlie', email: 'charlie@example.com' },
      ];

      // Apply search filter if provided
      let filteredUsers = users;
      if (search) {
        const searchLower = search.toLowerCase();
        filteredUsers = users.filter(user => 
          user.name.toLowerCase().includes(searchLower) ||
          user.email.toLowerCase().includes(searchLower)
        );
      }

      // Sort users safely
      const sortedUsers = [...filteredUsers].sort((a, b) => {
        const aVal = a[sort];
        const bVal = b[sort];
        const comparison = aVal > bVal ? 1 : aVal < bVal ? -1 : 0;
        return order === 'desc' ? -comparison : comparison;
      });

      // Paginate safely
      const paginatedUsers = sortedUsers.slice(offset, offset + limit);

      // Return with metadata - helpful for API consumers
      safeResponse(res, {
        data: paginatedUsers,
        meta: {
          total: filteredUsers.length,
          limit,
          offset,
          hasMore: offset + limit < filteredUsers.length
        }
      });

    } catch (error) {
      console.error('Users endpoint error:', {
        message: error.message,
        stack: process.env.NODE_ENV === 'development' ? error.stack : undefined
      });
      safeErrorResponse(res, 'Failed to retrieve users');
    }
  }
);

// ===== ERROR HANDLING =====

// Global error handler - must be after all routes
app.use((err, req, res, next) => {
  // Log the error securely
  console.error('Unhandled error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });

  // Determine status code
  const status = err.status || 500;

  // Send appropriate error response
  const isDevelopment = process.env.NODE_ENV === 'development';
  safeErrorResponse(res, 
    err.message || 'Internal server error',
    status
  );
});

// 404 handler - must be last
app.use((req, res) => {
  safeErrorResponse(
    res, 
    `Route ${req.method} ${req.path} not found`,
    404
  );
});

// ===== SERVER SETUP & GRACEFUL SHUTDOWN =====

const server = app.listen(process.env.PORT || 3000, () => {
  console.log(`Server running on port ${process.env.PORT || 3000}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

const gracefulShutdown = (signal) => {
  console.log(`\n${signal} received. Starting graceful shutdown...`);

  // Stop accepting new connections
  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force shutdown after 10 seconds if stuck
  const timeout = setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 10000);

  // Clear timeout if shutdown completes
  server.on('close', () => clearTimeout(timeout));
};

// Handle shutdown signals
process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions - prevent silent failures
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', {
    message: err.message,
    stack: err.stack
  });
  // Exit to allow process manager to restart
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', {
    reason: reason,
    promise: promise
  });
  // Exit to allow process manager to restart
  process.exit(1);
});

module.exports = app;

