#!/usr/bin/env node

import { readFileSync } from 'fs';
import { Client } from 'pg';
import https from 'https';

// Read environment variables from .env.test
const envContent = readFileSync('.env.test', 'utf8');
const envVars = {};
for (const line of envContent.split('\n')) {
  const [key, ...valueParts] = line.split('=');
  if (key && !key.startsWith('#') && valueParts.length > 0) {
    const value = valueParts.join('=').trim();
    if (value) {
      envVars[key.trim()] = value;
    }
  }
}

console.log('========================================');
console.log('Environment Variable Validation Tests');
console.log('========================================\n');

// Test results tracking
const results = {
  passed: 0,
  failed: 0,
  skipped: 0,
  tests: []
};

function recordTest(name, status, message, details = null) {
  const test = { name, status, message, details, timestamp: new Date().toISOString() };
  results.tests.push(test);

  if (status === 'PASS') {
    results.passed++;
    console.log(`✅ PASS: ${name}`);
  } else if (status === 'FAIL') {
    results.failed++;
    console.log(`❌ FAIL: ${name}`);
  } else {
    results.skipped++;
    console.log(`⏭️  SKIP: ${name}`);
  }

  if (message) {
    console.log(`   ${message}`);
  }
  if (details) {
    console.log(`   Details: ${details}`);
  }
  console.log();
}

async function testDatabaseConnection() {
  console.log('📊 Testing Database Connection...\n');

  const databaseUrl = envVars['DATABASE_URL'];
  if (!databaseUrl) {
    recordTest('DATABASE_URL exists', 'FAIL', 'DATABASE_URL not found in .env.test');
    return;
  }

  recordTest('DATABASE_URL exists', 'PASS', 'Found DATABASE_URL');

  // Parse DATABASE_URL
  try {
    const url = new URL(databaseUrl);
    recordTest('DATABASE_URL format', 'PASS', 'Valid URL format', 
      `Host: ${url.hostname}, Port: ${url.port}, DB: ${url.pathname.substring(1)}`);

    // Attempt connection with timeout
    const client = new Client({
      connectionString: databaseUrl,
      connectionTimeoutMillis: 5000,
    });

    try {
      await client.connect();
      recordTest('Database connectivity', 'PASS', 'Successfully connected to database');

      // Run a simple query
      const result = await client.query('SELECT version()');
      recordTest('Database query execution', 'PASS', 'Successfully executed query',
        `PostgreSQL version detected`);

      await client.end();
    } catch (error) {
      if (error.code === 'ECONNREFUSED') {
        recordTest('Database connectivity', 'FAIL', 'Connection refused - database not accessible',
          `Error: ${error.message}`);
      } else if (error.code === 'ENOTFOUND') {
        recordTest('Database connectivity', 'FAIL', 'Host not found - DNS resolution failed',
          `Error: ${error.message}`);
      } else if (error.code === '3D000') {
        recordTest('Database connectivity', 'FAIL', 'Database does not exist',
          `Error: ${error.message}`);
      } else if (error.code === '28P01') {
        recordTest('Database connectivity', 'FAIL', 'Authentication failed - invalid credentials',
          `Error: ${error.message}`);
      } else {
        recordTest('Database connectivity', 'FAIL', 'Connection or query failed',
          `Code: ${error.code}, Error: ${error.message}`);
      }
      try { await client.end(); } catch (e) {}
    }
  } catch (error) {
    recordTest('DATABASE_URL format', 'FAIL', 'Invalid URL format', error.message);
  }
}

function testApiRequest(name, apiKey, hostname, path, method = 'GET') {
  return new Promise((resolve) => {
    if (!apiKey) {
      recordTest(`${name} - API Key exists`, 'FAIL', 'API key not found in .env.test');
      resolve();
      return;
    }

    recordTest(`${name} - API Key exists`, 'PASS', `API key found (length: ${apiKey.length}`);

    // Check for canary value
    if (apiKey.includes('CANARY')) {
      recordTest(`${name} - Canary detection`, 'PASS', 'Canary value detected - likely test credentials');
      recordTest(`${name} - Connectivity`, 'SKIP', 'Skipping connectivity test for canary value');
      resolve();
      return;
    }

    // Make test request
    const options = {
      hostname,
      path,
      method,
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'User-Agent': 'Environment-Validator/1.0'
      },
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => {
        data += chunk;
      });

      res.on('end', () => {
        if (res.statusCode === 200) {
          recordTest(`${name} - API connectivity`, 'PASS', `Successfully connected to ${hostname}`,
            `Status: ${res.statusCode}`);
        } else if (res.statusCode === 401) {
          recordTest(`${name} - API connectivity`, 'FAIL', 'Authentication failed - invalid API key',
            `Status: ${res.statusCode}`);
        } else {
          recordTest(`${name} - API connectivity`, 'PASS', `Received response from ${hostname}`,
            `Status: ${res.statusCode}`);
        }
        resolve();
      });
    });

    req.on('error', (error) => {
      if (error.code === 'ENOTFOUND') {
        recordTest(`${name} - API connectivity`, 'SKIP', 'DNS resolution failed - network issue',
          `Error: ${error.message}`);
      } else {
        recordTest(`${name} - API connectivity`, 'FAIL', 'Request failed',
          `Error: ${error.message}`);
      }
      resolve();
    });

    req.on('timeout', () => {
      req.destroy();
      recordTest(`${name} - API connectivity`, 'FAIL', 'Request timed out');
      resolve();
    });

    req.end();
  });
}

async function testAnthropicApi() {
  console.log('🤖 Testing Anthropic API Key...\n');

  const apiKey = envVars['ANTHROPIC_API_KEY'];
  await testApiRequest(
    'Anthropic API',
    apiKey,
    'api.anthropic.com',
    '/v1/models',
    'GET'
  );
}

async function testStripeApi() {
  console.log('💳 Testing Stripe API Key...\n');

  const apiKey = envVars['STRIPE_SECRET_KEY'];

  if (!apiKey) {
    recordTest('Stripe - API Key exists', 'FAIL', 'STRIPE_SECRET_KEY not found in .env.test');
    return;
  }

  recordTest('Stripe - API Key exists', 'PASS', `API key found (prefix: ${apiKey.substring(0, 7)}...)`);

  // Check for canary value
  if (apiKey.includes('CANARY')) {
    recordTest('Stripe - Canary detection', 'PASS', 'Canary value detected - likely test credentials');
    recordTest('Stripe - Key type', 'PASS', 'Test key detected (live_ prefix in canary)');
    recordTest('Stripe - Connectivity', 'SKIP', 'Skipping connectivity test for canary value');
    return;
