#!/usr/bin/env node

/**
 * Environment Variable Validation Script
 * Tests connectivity and validity of credentials in .env.test
 * Uses only Node.js built-in modules
 */

const fs = require('fs');
const https = require('https');

// Test results tracking
const results = {
  passed: 0,
  failed: 0,
  skipped: 0,
  tests: []
};

function printTest(status, name, message, details) {
  const test = { name, status, message, details, timestamp: new Date().toISOString() };
  results.tests.push(test);

  let emoji, color;
  if (status === 'PASS') {
    emoji = '✅'; color = '\x1b[32m';
    results.passed++;
  } else if (status === 'FAIL') {
    emoji = '❌'; color = '\x1b[31m';
    results.failed++;
  } else {
    emoji = '⏭️ '; color = '\x1b[33m';
    results.skipped++;
  }

  console.log(`${color}${emoji} PASS: ${name}\x1b[0m`);
  if (message) console.log(`   ${message}`);
  if (details) console.log(`   Details: ${details}`);
  console.log('');
}

function loadEnvFile(filepath) {
  try {
    const content = fs.readFileSync(filepath, 'utf8');
    const envVars = {};
    for (const line of content.split('\n')) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eqIndex = line.indexOf('=');
      if (eqIndex > 0) {
        const key = line.substring(0, eqIndex).trim();
        const value = line.substring(eqIndex + 1).trim();
        if (value) envVars[key] = value;
      }
    }
    return envVars;
  } catch (error) {
    console.error(`Error: Cannot read ${filepath}`);
    process.exit(1);
  }
}

function containsCanary(value) {
  return value && value.includes('CANARY');
}

function testDatabase(envVars) {
  console.log('📊 Testing Database Connection...\n');

  const databaseUrl = envVars['DATABASE_URL'];
  if (!databaseUrl) {
    printTest('FAIL', 'DATABASE_URL exists', 'DATABASE_URL not found in .env.test');
    return;
  }

  printTest('PASS', 'DATABASE_URL exists', 'Found DATABASE_URL');

  // Parse URL
  try {
    const url = new URL(databaseUrl);
    const info = `Host: ${url.hostname}, Port: ${url.port || 'default'}, DB: ${url.pathname.substring(1)}`;
    printTest('PASS', 'DATABASE_URL format', 'Valid URL format', info);

    // Check for canary
    if (containsCanary(databaseUrl)) {
      printTest('PASS', 'Canary detection', 'Canary value detected - likely test credentials');
      printTest('SKIP', 'Database connectivity', 'Skipping connection test for canary value');
      return;
    }

    // Try to connect (we'll use a simple TCP check since we don't have pg module)
    printTest('SKIP', 'Database connectivity', 
             'PostgreSQL module not installed - cannot test actual connection',
             'Install: npm install pg');

  } catch (error) {
    printTest('FAIL', 'DATABASE_URL format', 'Invalid URL format', error.message);
  }
}

function testApiRequest(name, apiKey, hostname, path, method = 'GET', authPrefix = 'Bearer') {
  return new Promise((resolve) => {
    if (!apiKey) {
      printTest('FAIL', `${name} - API Key exists`, 'API key not found in .env.test');
      resolve();
      return;
    }

    printTest('PASS', `${name} - API Key exists`, `API key found (length: ${apiKey.length})`);

    // Check for canary
    if (containsCanary(apiKey)) {
      printTest('PASS', `${name} - Canary detection`, 'Canary value detected - likely test credentials');
      printTest('SKIP', `${name} - API connectivity`, 'Skipping connectivity test for canary value');
      resolve();
      return;
    }

    // Make test request
    const options = {
      hostname,
      path,
      method,
      headers: {
        'Authorization': `${authPrefix} ${apiKey}`,
        'User-Agent': 'Env-Validator/1.0'
      },
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';

      res.on('data', (chunk) => { data += chunk; });

      res.on('end', () => {
        if (res.statusCode === 200) {
          printTest('PASS', `${name} - API connectivity`, 
                   `Successfully connected to ${hostname}`,
                   `Status: ${res.statusCode}`);
        } else if (res.statusCode === 401) {
          printTest('FAIL', `${name} - API connectivity`,
                   'Authentication failed - invalid API key',
                   `Status: ${res.statusCode}`);
        } else {
          printTest('PASS', `${name} - API connectivity`,
                   `Received response from ${hostname}`,
                   `Status: ${res.statusCode}`);
        }
        resolve();
      });
    });

    req.on('error', (error) => {
      if (error.code === 'ENOTFOUND' || error.code === 'EAI_AGAIN') {
        printTest('SKIP', `${name} - API connectivity`,
                 'DNS resolution failed - network issue',
                 `Error: ${error.message}`);
      } else if (error.code === 'ETIMEDOUT' || error.code === 'ECONNRESET') {
        printTest('FAIL', `${name} - API connectivity`,
                 'Connection timed out or failed',
                 `Error: ${error.message}`);
      } else {
        printTest('FAIL', `${name} - API connectivity`,
                 'Request failed',
                 `Error: ${error.message}`);
      }
      resolve();
    });

    req.on('timeout', () => {
      req.destroy();
      printTest('FAIL', `${name} - API connectivity`, 'Request timed out');
      resolve();
    });

    req.end();
  });
}

async function testAnthropicApi(envVars) {
  console.log('🤖 Testing Anthropic API Key...\n');

  const apiKey = envVars['ANTHROPIC_API_KEY'];

  if (!apiKey) {
    printTest('FAIL', 'Anthropic - API Key exists', 'ANTHROPIC_API_KEY not found in .env.test');
    return;
  }

  printTest('PASS', 'Anthropic - API Key exists', `API key found (length: ${apiKey.length})`);

  // Check format
  if (!apiKey.startsWith('sk-ant-')) {
    printTest('FAIL', 'Anthropic - Key format', 'Invalid Anthropic API key format');
    return;
  }
  printTest('PASS', 'Anthropic - Key format', 'Valid Anthropic API key format (starts with sk-ant-)');

  // Check for canary
  if (containsCanary(apiKey)) {
    printTest('PASS', 'Anthropic - Canary detection', 'Canary value detected - likely test credentials');
    printTest('SKIP', 'Anthropic - API connectivity', 'Skipping connectivity test for canary value');
    return;
  }

  await testApiRequest('Anthropic API', apiKey, 'api.anthropic.com', '/v1/models', 'GET', 'Bearer');
}

async function testStripeApi(envVars) {
  console.log('💳 Testing Stripe API Key...\n');

  const apiKey = envVars['STRIPE_SECRET_KEY'];

  if (!apiKey) {
    printTest('FAIL', 'Stripe - API Key exists', 'STRIPE_SECRET_KEY not found in .env.test');
    return;
  }

  const prefix = apiKey.substring(0, 7) + '...';
  printTest('PASS', 'Stripe - API Key exists', `API key found`, `Prefix: ${prefix}, Length: ${apiKey.length}`);

  // Check key type
  let keyType;
  if (apiKey.startsWith('sk_test_')) {
    keyType = 'Test key';
  } else if (apiKey.startsWith('sk_live_')) {
    keyType = 'Live key';
  } else {
    printTest('FAIL', 'Stripe - Key type', 'Unknown key format');
    return;
  }
  printTest('PASS', 'Stripe - Key type', keyType);

  // Check for canary
  if (containsCanary(apiKey)) {
    printTest('PASS', 'Stripe - Canary detection', 'Canary value detected - likely test credentials');
    printTest('SKIP', 'Stripe - API connectivity', 'Skipping connectivity test for canary value');
    return;
  }

  await testApiRequest('Stripe API', apiKey, 'api.stripe.com', '/v1/charges', 'GET', 'Bearer');
}

function testAwsCredentials(envVars) {
  console.log('☁️  Testing AWS Credentials...\n');

  const accessKeyId = envVars['AWS_ACCESS_KEY_ID'];
  const secretAccessKey = envVars['AWS_SECRET_ACCESS_KEY'];

  if (!accessKeyId || !secretAccessKey) {
    printTest('FAIL', 'AWS - Credentials exist', 'AWS credentials not found in .env.test');
    return;
  }

  printTest('PASS', 'AWS - Access Key ID exists', `Access Key ID: ${accessKeyId}`);
  printTest('PASS', 'AWS - Secret Access Key exists', `Secret Access Key length: ${secretAccessKey.length}`);

  // Check for canary
  if (containsCanary(accessKeyId) || containsCanary(secretAccessKey)) {
    printTest('PASS', 'AWS - Canary detection', 'Canary value detected - likely test credentials');
  } else {
    // Basic format validation
    if (accessKeyId.length === 20) {
      printTest('PASS', 'AWS - Access Key format', 'Access key ID has correct length (20 chars)');
    } else {
      printTest('FAIL', 'AWS - Access Key format', 
               `Incorrect length (found: ${accessKeyId.length}, expected: 20)`);
    }

    if (secretAccessKey.length === 40) {
      printTest('PASS', 'AWS - Secret Key format', 'Secret access key has correct length (40 chars)');
    } else {
      printTest('FAIL', 'AWS - Secret Key format', 
               `Incorrect length (found: ${secretAccessKey.length}, expected: 40)`);
    }
  }

  printTest('SKIP', 'AWS - Connectivity', 
           'AWS SDK not available for connectivity test',
           'Install: npm install @aws-sdk/client-sts');
}

function testLogfireToken(envVars) {
  console.log('🔥 Testing Logfire Token...\n');

  const token = envVars['LOGFIRE_TOKEN'];

  if (!token) {
    printTest('FAIL', 'Logfire - Token exists', 'LOGFIRE_TOKEN not found in .env.test');
    return;
  }

  printTest('PASS', 'Logfire - Token exists', `Token found (length: ${token.length})`);

  // Check for canary
  if (containsCanary(token)) {
    printTest('PASS', 'Logfire - Canary detection', 'Canary value detected - likely test credentials');
  }

  printTest('SKIP', 'Logfire - Connectivity', 'Logfire endpoint requires SDK - skipping');
}

function printSummary() {
  console.log('========================================');
  console.log('Test Summary');
  console.log('========================================\n');
  console.log(`✅ Passed: ${results.passed}`);
  console.log(`❌ Failed: ${results.failed}`);
  console.log(`⏭️  Skipped: ${results.skipped}`);
  console.log(`📊 Total:  ${results.tests.length}\n`);

  if (results.failed > 0) {
    console.log('⚠️  Some credentials may be invalid or stale.');
    console.log('   Review the failed tests above for details.\n');
    return 1;
  } else {
    console.log('✅ All tests that could run completed successfully.');
    console.log('   (Some tests were skipped for canary values or lack of dependencies)\n');
    return 0;
  }
}

async function main() {
  console.log('========================================');
  console.log('Environment Variable Validation Tests');
  console.log('========================================\n');

  const envVars = loadEnvFile('.env.test');

  await testDatabase(envVars);
  await testAnthropicApi(envVars);
  await testStripeApi(envVars);
