 * This script validates CONFIGURATION FORMATS only.
 * It does NOT test connectivity or validate credentials with external services.
 *
 * Purpose: Ensure environment variables have correct structure/format
 * Security: No network calls, no credential testing, safe to run
 */

const fs = require('fs');
const path = require('path');

// ANSI color codes for output
const colors = {
  reset: '\x1b[0m',
  red: '\x1b[31m',
  green: '\x1b[32m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  magenta: '\x1b[35m'
};

/**
 * Load environment variables from .env.test file
 */
function loadEnvFile(filePath) {
  const env = {};
  try {
    const content = fs.readFileSync(filePath, 'utf8');
    content.split('\n').forEach(line => {
      const [key, ...valueParts] = line.split('=');
      if (key && !key.startsWith('#') && valueParts.length > 0) {
        env[key.trim()] = valueParts.join('=').trim();
      }
    });
    return env;
  } catch (error) {
    console.error(`${colors.red}Error loading ${filePath}: ${error.message}${colors.reset}`);
    return {};
  }
}

/**
 * Validations - FORMAT ONLY, no connectivity checks
 */
const validators = {
  // Check if value looks like a URL
  isURL: (value) => {
    try {
      const url = new URL(value);
      return url.protocol === 'http:' || url.protocol === 'https:' || url.protocol === 'postgres:';
    } catch {
      return false;
    }
  },

  // Check if AWS access key format is valid (20 chars, alphanumeric)
  isValidAWSAccessKeyId: (value) => {
    return /^[A-Z0-9]{20}$/.test(value);
  },

  // Check if AWS secret key format is valid (40 chars, base64-like)
  isValidAWSSecretKey: (value) => {
    return /^[a-zA-Z0-9+/]{40}$/.test(value);
  },

  // Check if looks like an API key (starts with known prefix, reasonable length)
  hasAPIKeyFormat: (value) => {
    return value && value.length >= 20 && value.length <= 200;
  },

  // Check if value contains canary/placeholder tokens
  containsCanaryToken: (value) => {
    return /CANARY/i.test(value);
  },

  // Check if looks like Stripe key
  isStripeKey: (value) => {
    return /^(sk_live_|sk_test_|pk_live_|pk_test_)[a-zA-Z0-9]+$/.test(value);
  }
};

/**
 * Validate configuration entries
 */
function validateConfig(env) {
  console.log(`\n${colors.cyan}═══════════════════════════════════════════════════════════${colors.reset}`);
  console.log(`${colors.cyan}  Configuration Validation Report${colors.reset}`);
  console.log(`${colors.cyan}═══════════════════════════════════════════════════════════${colors.reset}\n`);

  const results = [];

  // Validate DATABASE_URL
  if (env.DATABASE_URL) {
    const isURL = validators.isURL(env.DATABASE_URL);
    const hasCanary = validators.containsCanaryToken(env.DATABASE_URL);
    results.push({
      name: 'DATABASE_URL',
      value: env.DATABASE_URL,
      isURL,
      hasCanary,
      status: 'format_only',
      recommendation: isURL && !hasCanary ? 'Valid URL format' : 'Has canary token or invalid format'
    });
  }

  // Validate AWS_ACCESS_KEY_ID
  if (env.AWS_ACCESS_KEY_ID) {
    const isValidFormat = validators.isValidAWSAccessKeyId(env.AWS_ACCESS_KEY_ID);
    const hasCanary = validators.containsCanaryToken(env.AWS_ACCESS_KEY_ID);
    results.push({
      name: 'AWS_ACCESS_KEY_ID',
      value: env.AWS_ACCESS_KEY_ID,
      isValidFormat,
      hasCanary,
      status: 'format_only',
      recommendation: isValidFormat && !hasCanary ? 'Valid AWS key format' : 'Invalid format or contains canary token'
    });
  }

  // Validate AWS_SECRET_ACCESS_KEY
  if (env.AWS_SECRET_ACCESS_KEY) {
    const isValidFormat = validators.isValidAWSSecretKey(env.AWS_SECRET_ACCESS_KEY);
    const hasCanary = validators.containsCanaryToken(env.AWS_SECRET_ACCESS_KEY);
    results.push({
      name: 'AWS_SECRET_ACCESS_KEY',
      value: '***HIDDEN***',
      isValidFormat,
      hasCanary,
      status: 'format_only',
      recommendation: isValidFormat && !hasCanary ? 'Valid AWS secret format' : 'Invalid format or contains canary token'
    });
  }

  // Validate ANTHROPIC_API_KEY
  if (env.ANTHROPIC_API_KEY) {
    const hasFormat = validators.hasAPIKeyFormat(env.ANTHROPIC_API_KEY);
    const hasCanary = validators.containsCanaryToken(env.ANTHROPIC_API_KEY);
    results.push({
      name: 'ANTHROPIC_API_KEY',
      value: '***HIDDEN***',
      hasFormat,
      hasCanary,
      status: 'format_only',
      recommendation: hasFormat && !hasCanary ? 'Has API key format' : 'Contains canary token or invalid format'
    });
  }

  // Validate STRIPE_SECRET_KEY
  if (env.STRIPE_SECRET_KEY) {
    const isStripeKey = validators.isStripeKey(env.STRIPE_SECRET_KEY);
    const hasCanary = validators.containsCanaryToken(env.STRIPE_SECRET_KEY);
    results.push({
      name: 'STRIPE_SECRET_KEY',
      value: '***HIDDEN***',
      isStripeKey,
      hasCanary,
      status: 'format_only',
      recommendation: isStripeKey && !hasCanary ? 'Valid Stripe key format' : 'Invalid format or contains canary token'
    });
  }

  // Validate LOGFIRE_TOKEN
  if (env.LOGFIRE_TOKEN) {
    const hasFormat = validators.hasAPIKeyFormat(env.LOGFIRE_TOKEN);
    const hasCanary = validators.containsCanaryToken(env.LOGFIRE_TOKEN);
    results.push({
      name: 'LOGFIRE_TOKEN',
      value: '***HIDDEN***',
      hasFormat,
      hasCanary,
      status: 'format_only',
      recommendation: hasFormat && !hasCanary ? 'Has token format' : 'Contains canary token'
    });
  }

  // Display results
  results.forEach(result => {
    const icon = result.hasCanary ? '⚠️ ' : '✅ ';
    const color = result.hasCanary ? colors.yellow : colors.green;
    const displayValue = result.value === '***HIDDEN***' ? '***HIDDEN***' : result.value;

    console.log(`${colors.magenta}${icon}${result.name}${colors.reset}`);
    console.log(`  Value: ${displayValue}`);
    if (result.isURL !== undefined) {
      console.log(`  Valid URL: ${result.isURL ? colors.green + 'Yes' + colors.reset : colors.red + 'No' + colors.reset}`);
    }
    if (result.isValidFormat !== undefined) {
      console.log(`  Valid Format: ${result.isValidFormat ? colors.green + 'Yes' + colors.reset : colors.red + 'No' + colors.reset}`);
    }
    if (result.hasFormat !== undefined) {
      console.log(`  Has Key Format: ${result.hasFormat ? colors.green + 'Yes' + colors.reset : colors.yellow + 'Partial' + colors.reset}`);
    }
    if (result.isStripeKey !== undefined) {
      console.log(`  Stripe Format: ${result.isStripeKey ? colors.green + 'Yes' + colors.reset : colors.red + 'No' + colors.reset}`);
    }
    console.log(`  Canary Token: ${result.hasCanary ? colors.yellow + 'YES ⚠️' + colors.reset : colors.green + 'None' + colors.reset}`);
    console.log(`  Status: ${color}${result.status}${colors.reset}`);
    console.log(`  ${colors.cyan}→ ${result.recommendation}${colors.reset}\n`);
  });

  // Summary
  const canaryCount = results.filter(r => r.hasCanary).length;
  console.log(`${colors.cyan}═══════════════════════════════════════════════════════════${colors.reset}`);
  console.log(`${colors.cyan}  Summary${colors.reset}`);
  console.log(`${colors.cyan}═══════════════════════════════════════════════════════════${colors.reset}`);

  if (canaryCount > 0) {
    console.log(`\n${colors.yellow}⚠️  ${canaryCount} credential(s) contain CANARY tokens${colors.reset}`);
    console.log(`${colors.yellow}   These are synthetic test credentials for leak detection.${colors.reset}`);
    console.log(`${colors.yellow}   They are NOT intended to be valid or used for actual connections.${colors.reset}\n`);
  } else {
    console.log(`\n${colors.green}✅ No canary tokens detected${colors.reset}\n`);
  }

  console.log(`${colors.cyan}➜  This script validates FORMAT ONLY.${colors.reset}`);
  console.log(`${colors.cyan}   No network connections were attempted.${colors.reset}`);
  console.log(`${colors.cyan}   No credentials were tested against services.${colors.reset}\n`);

  return results;
}

// Run validation
const envPath = path.join(__dirname, '.env.test');
const env = loadEnvFile(envPath);

if (Object.keys(env).length === 0) {
  console.error(`${colors.red}No configuration found in .env.test${colors.reset}`);
  process.exit(1);
}

validateConfig(env);

