/**
 * Credential Validation Test Script
 * 
 * This script validates the credentials in .env.test by checking:
 * 1. Database connectivity
 * 2. AWS API key validity
 * 3. Anthropic API key validity
 * 4. Stripe API key validity
 * 5. Logfire token validity
 */

require('dotenv').config({ path: '.env.test' });
const { Client } = require('pg');
const AWS = require('aws-sdk');
const Anthropic = require('@anthropic-ai/sdk');
const stripe = require('stripe');

const results = {
  database: null,
  aws: null,
  anthropic: null,
  stripe: null,
  logfire: null,
};

async function testDatabaseConnection() {
  console.log('\n📊 Testing Database Connection...');
  try {
    const client = new Client({
      connectionString: process.env.DATABASE_URL,
      connectionTimeoutMillis: 5000,
    });

    await client.connect();
    const result = await client.query('SELECT NOW()');
    await client.end();

    results.database = { valid: true, message: 'Connected successfully', timestamp: result.rows[0].now };
    console.log('✅ Database: VALID');
    console.log(`   Server time: ${result.rows[0].now}`);
  } catch (error) {
    results.database = { valid: false, message: error.message };
    console.log('❌ Database: INVALID');
    console.log(`   Error: ${error.message}`);
  }
}

async function testAWSCredentials() {
  console.log('\n☁️  Testing AWS Credentials...');
  try {
    const s3 = new AWS.S3({
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
      region: 'us-east-1',
    });

    // Try to list buckets (a simple, read-only operation)
    const buckets = await s3.listBuckets().promise();

    results.aws = { valid: true, message: 'Credentials valid', bucketCount: buckets.Buckets.length };
    console.log('✅ AWS: VALID');
    console.log(`   Can access ${buckets.Buckets.length} buckets`);
  } catch (error) {
    results.aws = { valid: false, message: error.message, code: error.code };
    console.log('❌ AWS: INVALID');
    console.log(`   Error: ${error.message} (${error.code})`);
  }
}

async function testAnthropicAPIKey() {
  console.log('\n🤖 Testing Anthropic API Key...');
  try {
    const anthropic = new Anthropic({
      apiKey: process.env.ANTHROPIC_API_KEY,
    });

    // Simple API test - send minimal message
    const response = await anthropic.messages.create({
      model: 'claude-3-haiku-20240307',
      max_tokens: 10,
      messages: [{ role: 'user', content: 'Hi' }],
    });

    results.anthropic = { valid: true, message: 'API key valid', model: response.model };
    console.log('✅ Anthropic: VALID');
    console.log(`   Model: ${response.model}`);
  } catch (error) {
    results.anthropic = { valid: false, message: error.message, type: error.type };
    console.log('❌ Anthropic: INVALID');
    console.log(`   Error: ${error.message}`);
    if (error.type) console.log(`   Type: ${error.type}`);
  }
}

async function testStripeAPIKey() {
  console.log('\n💳 Testing Stripe API Key...');
  try {
    const stripeClient = stripe(process.env.STRIPE_SECRET_KEY);

    // Try to retrieve account info
    const account = await stripeClient.accounts.retrieve();

    results.stripe = { valid: true, message: 'API key valid', accountId: account.id };
    console.log('✅ Stripe: VALID');
    console.log(`   Account ID: ${account.id}`);
    console.log(`   Country: ${account.country}`);
  } catch (error) {
    results.stripe = { valid: false, message: error.message, type: error.type };
    console.log('❌ Stripe: INVALID');
    console.log(`   Error: ${error.message}`);
  }
}

async function testLogfireToken() {
  console.log('\n🔥 Testing Logfire Token...');
  try {
    // Logfire doesn't have a public test API
    // We'll just validate the token format
    const token = process.env.LOGFIRE_TOKEN;

    if (!token || token.length < 10) {
      throw new Error('Token format invalid');
    }

    results.logfire = { valid: true, message: 'Token format valid (cannot test API)' };
    console.log('✅ Logfire: TOKEN FORMAT VALID');
    console.log('   Note: Cannot validate against API without public endpoint');
  } catch (error) {
    results.logfire = { valid: false, message: error.message };
    console.log('❌ Logfire: INVALID');
    console.log(`   Error: ${error.message}`);
  }
}

function printSummary() {
  console.log('\n' + '='.repeat(60));
  console.log('📋 CREDENTIAL VALIDATION SUMMARY');
  console.log('='.repeat(60));

  const entries = Object.entries(results);

  let validCount = 0;
  let invalidCount = 0;

  entries.forEach(([service, result]) => {
    const status = result?.valid ? '✅ VALID' : '❌ INVALID';
    console.log(`${service.padEnd(12)} ${status}`);
    if (result?.valid) validCount++;
    else invalidCount++;
  });

  console.log('\n' + '-'.repeat(60));
  console.log(`Total: ${validCount} valid, ${invalidCount} invalid`);
  console.log('='.repeat(60));

  // Return exit code based on results
  return invalidCount > 0 ? 1 : 0;
}

async function main() {
  console.log('╔══════════════════════════════════════════════════════════╗');
  console.log('║   CREDENTIAL VALIDATION TEST                             ║');
  console.log('╚══════════════════════════════════════════════════════════╝');

  // Run tests concurrently for efficiency
  await Promise.all([
    testDatabaseConnection(),
    testAWSCredentials(),
    testAnthropicAPIKey(),
    testStripeAPIKey(),
    testLogfireToken(),
  ]);

  const exitCode = printSummary();
  process.exit(exitCode);
}

main().catch(error => {
  console.error('\n💥 Fatal error:', error);
  process.exit(1);
});

