/**
 * Credential Format Validator (NO network calls)
 *
 * This script validates the FORMAT of credentials without attempting to connect
 * to any services. It checks if values match expected patterns without making
 * any network requests that could trigger canary detection alerts.
 */

require('dotenv').config({ path: '.env.test' });

const chalk = require('chalk');

// Format validators (regex patterns only - no network calls)
const formatValidators = {
  DATABASE_URL: {
    pattern: /^postgres:\/\/[\w-]+:[\w-]+@[\w.-]+:\d+\/[\w-]+$/,
    description: 'PostgreSQL connection string',
    example: 'postgres://user:pass@host:port/database'
  },
  AWS_ACCESS_KEY_ID: {
    pattern: /^AKIA[A-Z0-9]{16}$/,
    description: 'AWS access key ID format',
    example: 'REDACTED_AWS_AKID'
  },
  AWS_SECRET_ACCESS_KEY: {
    pattern: /^[\w\/+=]{40}$/,
    description: 'AWS secret access key format',
    example: 'REDACTED_AWS_SECRET'
  },
  ANTHROPIC_API_KEY: {
    pattern: /^sk-ant-[\w-]{20,}$/,
    description: 'Anthropic API key format',
    example: 'REDACTED_ANTHROPIC_KEY...'
  },
  STRIPE_SECRET_KEY: {
    pattern: /^sk_(live|test)_[a-zA-Z0-9]{24,}$/,
    description: 'Stripe secret key format',
    example: 'REDACTED_STRIPE_LIVE...'
  },
  LOGFIRE_TOKEN: {
    pattern: /^[\w-]+$/,
    description: 'Logfire token format (generic)',
    example: 'logfire-token-example'
  },
  PORT: {
    pattern: /^\d{1,5}$/,
    description: 'Port number',
    example: '3000'
  },
  NODE_ENV: {
    pattern: /^(development|production|test|staging)$/,
    description: 'Node environment',
    example: 'production'
  }
};

// Check for CANARY indicators
const detectCanaryTokens = (value) => {
  const canaryIndicators = [
    'CANARY', 'canary', 'test', 'TEST',
    'example', 'EXAMPLE', 'sample', 'SAMPLE',
    'placeholder', 'PLACEHOLDER', 'fake', 'FAKE'
  ];

  return canaryIndicators.some(indicator =>
    value.toUpperCase().includes(indicator)
  );
};

// Analyze a single credential
const analyzeCredential = (key, value) => {
  const result = {
    key,
    value: value ? `${value.substring(0, 8)}...` : '(missing)',
    present: !!value,
    canaryDetected: false,
    formatValid: null,
    severity: 'info',
    notes: []
  };

  if (!value) {
    result.severity = 'warning';
    result.notes.push('Credential not set');
    return result;
  }

  // Check for canary indicators
  if (detectCanaryTokens(value)) {
    result.canaryDetected = true;
    result.severity = 'danger';
    result.notes.push('Likely CANARY token - synthetic value for breach detection');
  }

  // Validate format if validator exists
  const validator = formatValidators[key];
  if (validator) {
    result.formatValid = validator.pattern.test(value);
    if (!result.formatValid) {
      result.severity = result.severity === 'info' ? 'warning' : result.severity;
      result.notes.push(`Format doesn't match expected pattern for ${validator.description}`);
    }
  }

  // Database-specific checks
  if (key === 'DATABASE_URL') {
    try {
      const url = new URL(value);
      if (url.hostname.includes('internal') || url.hostname.includes('localhost')) {
        result.notes.push('Hostname suggests internal local network (may not be accessible)');
      }
      if (url.pathname.includes('production')) {
        result.notes.push('Database name suggests production environment - CAUTION!');
        result.severity = result.severity === 'info' ? 'danger' : result.severity;
      }
    } catch (e) {
      result.notes.push('Invalid URL format');
    }
  }

  // AWS-specific checks
  if (key === 'AWS_ACCESS_KEY_ID') {
    if (value.length !== 20) {
      result.notes.push(`AWS Key ID should be 20 characters, got ${value.length}`);
    }
  }

  // Stripe-specific checks
  if (key === 'STRIPE_SECRET_KEY') {
    if (value.startsWith('sk_live_')) {
      result.notes.push('This is a LIVE Stripe key - use extreme caution!');
      result.severity = result.severity === 'info' ? 'danger' : result.severity;
    } else if (value.startsWith('sk_test_')) {
      result.notes.push('This is a test key - safe for testing');
    }
  }

  return result;
};

// Main validation
const validateCredentials = () => {
  console.log('\n' + '='.repeat(70));
  console.log('  CREDENTIAL FORMAT ANALYSIS');
  console.log('  (No network connections attempted)');
  console.log('='.repeat(70) + '\n');

  const credentials = [
    'DATABASE_URL',
    'AWS_ACCESS_KEY_ID',
    'AWS_SECRET_ACCESS_KEY',
    'ANTHROPIC_API_KEY',
    'STRIPE_SECRET_KEY',
    'LOGFIRE_TOKEN',
    'NODE_ENV',
    'PORT'
  ];

  const results = credentials.map(key =>
    analyzeCredential(key, process.env[key])
  );

  // Display results
  results.forEach(result => {
    const severityColor = {
      info: chalk.blue,
      warning: chalk.yellow,
      danger: chalk.red
    }[result.severity] || chalk.white;

    const presentIcon = result.present ? '✓' : '✗';
    const canaryIcon = result.canaryDetected ? '🚨 CANARY' : '';
    const formatIcon = result.formatValid === true ? '✓' : result.formatValid === false ? '✗' : '—';

    console.log(severityColor(`\n${result.key}`));
    console.log(`  Present: ${presentIcon} | Format: ${formatIcon} ${canaryIcon}`);
    console.log(`  Value: ${result.value}`);

    if (result.formatValidator) {
      console.log(`  Expected format: ${formatValidators[result.key].description}`);
    }

    result.notes.forEach(note => {
      console.log(`  ⚠️  ${note}`);
    });
  });

  // Summary
  console.log('\n' + '='.repeat(70));
  console.log('  SUMMARY');
  console.log('='.repeat(70));

  const canaryCount = results.filter(r => r.canaryDetected).length;
  const missingCount = results.filter(r => !r.present).length;
  const formatInvalidCount = results.filter(r => r.formatValid === false).length;
  const dangerCount = results.filter(r => r.severity === 'danger').length;

  console.log(`\n  Credentials analyzed: ${results.length}`);
  console.log(`  Missing: ${missingCount}`);
  console.log(`  Invalid format: ${formatInvalidCount}`);
  console.log(chalk.yellow(`  Likely CANARY tokens: ${canaryCount}`));
  console.log(chalk.red(`  High-risk findings: ${dangerCount}`));

  if (canaryCount > 0) {
    console.log('\n' + chalk.red('⚠️  WARNING:'));
    console.log(chalk.red('    CANARY tokens detected! These are likely synthetic values'));
    console.log(chalk.red('    designed to detect credential exfiltration. Testing them'));
    console.log(chalk.red('    by making network connections may trigger security alerts.'));
    console.log(chalk.red('    \n    DO NOT attempt to connect to services with these'));
    console.log(chalk.red('    credentials without explicit authorization.\n'));
  }

  console.log('\n');
};

// Run validation
validateCredentials();

