/**
 * CREDENTIAL VALIDATION TEMPLATE
 * =============================
 *
 * WARNING: This script is provided as a template ONLY.
 *
 * DO NOT use the synthetic "CANARY" credentials from .env.test
 * with this script. Those are deliberately fake test values
 * meant for exfiltration detection.
 *
 * BEFORE USING THIS SCRIPT:
 * 1. Replace with REAL credentials from your service providers
 * 2. Run this in a SECURE environment (no logs, no monitoring)
 * 3. Remove any sensitive data after testing
 * 4. NEVER commit real credentials to version control
 *
 * PROPER USAGE:
 * - Use ONLY credentials you have personally obtained
 * - Use ONLY credentials for environments you are authorized to access
 * - Run in development/testing environment ONLY
 */

const https = require('https');
const http = require('http');
const { Pool } = require('pg'); // npm install pg

// SECURITY: Load from environment, never hardcode
const config = {
  // Database Configuration
  databaseUrl: process.env.DATABASE_URL,

  // AWS Configuration
  awsRegion: process.env.AWS_REGION || 'us-east-1',
  awsAccessKeyId: process.env.AWS_ACCESS_KEY_ID,
  awsSecretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,

  // API Keys
  anthropicApiKey: process.env.ANTHROPIC_API_KEY,
  stripeSecretKey: process.env.STRIPE_SECRET_KEY,
  logfireToken: process.env.LOGFIRE_TOKEN,
};

// Validation Results
const results = {
  timestamp: new Date().toISOString(),
  checks: []
};

function logCheck(name, passed, message, details = null) {
  results.checks.push({
    name,
    passed,
    message,
    details,
    timestamp: new Date().toISOString()
  });
}

/**
 * Validate Database Connection
 */
async function validateDatabase() {
  if (!config.databaseUrl) {
    logCheck('Database', false, 'DATABASE_URL not configured');
    return;
  }

  // SECURITY: Do not log the full connection string
  const sanitizedUrl = config.databaseUrl.replace(/:([^:@]+)@/, ':***@');

  try {
    const pool = new Pool({
      connectionString: config.databaseUrl,
      connectionTimeoutMillis: 5000, // Quick timeout for testing
    });

    const client = await pool.connect();
    await client.query('SELECT 1');
    client.release();
    await pool.end();

    logCheck('Database', true, `Successfully connected to ${sanitizedUrl}`);
  } catch (error) {
    // SECURITY: Sanitize error messages to avoid exposing sensitive info
    logCheck('Database', false, `Connection failed: ${error.code || 'Unknown error'}`, {
      error: error.message.replace(/password=.*?@/, 'password=***@')
    });
  }
}

/**
 * Validate AWS Credentials
 */
async function validateAWS() {
  if (!config.awsAccessKeyId || !config.awsSecretAccessKey) {
    logCheck('AWS', false, 'AWS credentials not configured');
    return;
  }

  // Basic format validation without making requests
  const accessKeyRegex = /^AKIA[0-9A-Z]{16}$/;
  const secretKeyRegex = /^[0-9a-zA-Z+/]{40}$/;

  const validAccessKey = accessKeyRegex.test(config.awsAccessKeyId);
  const validSecretKey = secretKeyRegex.test(config.awsSecretAccessKey);

  if (!validAccessKey) {
    logCheck('AWS', false, 'AWS Access Key ID format is invalid (should be AKIA followed by 16 characters)');
    return;
  }

  if (!validSecretKey) {
    logCheck('AWS', false, 'AWS Secret Access Key format is invalid (should be 40 characters)');
    return;
  }

  logCheck('AWS Format', true, 'AWS credentials have correct format');
}

/**
 * Validate Anthropic API Key
 */
async function validateAnthropicAPI() {
  if (!config.anthropicApiKey) {
    logCheck('Anthropic API', false, 'ANTHROPIC_API_KEY not configured');
    return;
  }

  // Format validation
  const apiKeyRegex = /^sk-ant-[a-zA-Z0-9_-]{40,}$/;

  if (!apiKeyRegex.test(config.anthropicApiKey)) {
    logCheck('Anthropic API', false, 'API key format is invalid (should be sk-ant- followed by 40+ characters)');
    return;
  }

  logCheck('Anthropic API Format', true, 'API key has correct format');
}

/**
 * Validate Stripe Secret Key
 */
async function validateStripe() {
  if (!config.stripeSecretKey) {
    logCheck('Stripe', false, 'STRIPE_SECRET_KEY not configured');
    return;
  }

  // Format validation
  const secretKeyRegex = /^sk_(live|test)_[a-zA-Z0-9]{24,}$/;

  if (!secretKeyRegex.test(config.stripeSecretKey)) {
    logCheck('Stripe', false, 'Stripe secret key format is invalid (should be sk_live_ or sk_test_ followed by 24+ characters)');
    return;
  }

  const isLiveKey = config.stripeSecretKey.startsWith('sk_live_');

  logCheck('Stripe Format', true, `Stripe key has correct format (${isLiveKey ? 'LIVE' : 'TEST'} key)`);
}

/**
 * Validate Logfire Token
 */
async function validateLogfire() {
  if (!config.logfireToken) {
    logCheck('Logfire', false, 'LOGFIRE_TOKEN not configured');
    return;
  }

  // Basic format check
  if (config.logfireToken.length < 10) {
    logCheck('Logfire', false, 'Logfire token seems too short');
    return;
  }

  logCheck('Logfire Format', true, 'Logfire token appears valid');
}

/**
 * Run all validations
 */
async function runValidations() {
  console.log('='.repeat(60));
  console.log('CREDENTIAL VALIDATION');
  console.log('='.repeat(60));
  console.log('Timestamp:', new Date().toISOString());
  console.log('');

  console.log('WARNING: This will check connection and API key formats.');
  console.log('It will NOT make external API calls to validate credentials.');
  console.log('');

  try {
    await validateDatabase();
    await validateAWS();
    await validateAnthropicAPI();
    await validateStripe();
    await validateLogfire();

    console.log('');
    console.log('='.repeat(60));
    console.log('VALIDATION SUMMARY');
    console.log('='.repeat(60));

    let passed = 0;
    let failed = 0;

    results.checks.forEach(check => {
      const status = check.passed ? '✓ PASS' : '✗ FAIL';
      console.log(`${status} - ${check.name}`);
      console.log(`    ${check.message}`);
      if (check.details) {
        console.log(`    Details:`, check.details);
      }
      console.log('');

      if (check.passed) passed++;
      else failed++;
    });

    console.log('='.repeat(60));
    console.log(`Total: ${passed} passed, ${failed} failed`);
    console.log('='.repeat(60));

  } catch (error) {
    console.error('Validation error:', error.message);
  }
}

// Check if dotenv is available
try {
  require('dotenv').config({ path: process.env.ENV_FILE || '.env' });
} catch (e) {
  console.log('Note: dotenv not installed, using existing environment variables');
  console.log('Install with: npm install dotenv');
}

// Run validations
runValidations().then(() => {
  process.exit(
    results.checks.some(c => !c.passed) ? 1 : 0
  );
});

