require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');

// ================================
// LOGGER CONFIGURATION
// ================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

const app = express();

// ================================
// SECURITY MIDDLEWARE
// ================================

// Helmet for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// CORS configuration
const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
app.use(cors({
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests from this IP, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', { ip: req.ip, path: req.path });
    res.status(429).json({ error: 'Too many requests from this IP, please try again later.' });
  }
});

app.use(limiter);

// Request body size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim())
  }
}));

// ================================
// INPUT SANITIZATION
// ================================

const sanitizeInput = (req, res, next) => {
  // Sanitize query parameters
  if (req.query) {
    Object.keys(req.query).forEach(key => {
      if (typeof req.query[key] === 'string') {
        // Remove potential XSS patterns
        req.query[key] = req.query[key]
          .replace(/[<>]/g, '')
          .replace(/javascript:/gi, '')
          .replace(/on\w+=/gi, '')
          .trim();
      }
    });
  }

  // Sanitize body
  if (req.body) {
    Object.keys(req.body).forEach(key => {
      if (typeof req.body[key] === 'string') {
        req.body[key] = req.body[key]
          .replace(/[<>]/g, '')
          .replace(/javascript:/gi, '')
          .trim();
      }
    });
  }

  next();
};

// ================================
// VALIDATION MIDDLEWARE
// ================================

const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { 
      errors: errors.array(), 
      ip: req.ip,
      path: req.path,
      method: req.method
    });
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array() 
    });
  }
  next();
};

const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ================================
// ROUTES
// ================================

// Health check endpoint
app.get('/health', 
  sanitizeInput,
  asyncHandler(async (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  })
);

// Users endpoint with validation
app.get('/users',
  sanitizeInput,
  [
    // Validate query parameters
    query('id').optional().isInt({ min: 1 }).withMessage('ID must be a positive integer'),
    query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    query('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a non-negative integer'),
    query('email').optional().isEmail().withMessage('Email must be valid'),
  ],
  validateRequest,
  asyncHandler(async (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Filter by ID if provided
    if (req.query.id) {
      const filteredUser = users.find(u => u.id === parseInt(req.query.id));
      if (!filteredUser) {
        return res.status(404).json({ 
          error: 'User not found',
          id: parseInt(req.query.id) 
        });
      }
      return res.json(filteredUser);
    }

    // Filter by email if provided
    if (req.query.email) {
      const filteredUser = users.find(u => u.email.toLowerCase() === req.query.email.toLowerCase());
      if (!filteredUser) {
        return res.status(404).json({ 
          error: 'User not found',
          email: req.query.email 
        });
      }
      return res.json(filteredUser);
    }

    // Apply pagination
    const limit = parseInt(req.query.limit) || users.length;
    const offset = parseInt(req.query.offset) || 0;
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: users.length,
        limit,
        offset,
        hasMore: offset + limit < users.length
      }
    });
  })
);

// ================================
// ERROR HANDLING
// ================================

// 404 handler - must come after all routes
app.use((req, res) => {
  logger.warn('Resource not found', { 
    path: req.path, 
    method: req.method, 
    ip: req.ip 
  });
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path 
  });
});

// Global error handler - must come last
app.use((err, req, res, next) => {
  // Handle CORS errors
  if (err.message === 'Not allowed by CORS') {
    logger.warn('CORS error', { 
      origin: req.headers.origin,
      path: req.path,
      ip: req.ip 
    });
    return res.status(403).json({ 
      error: 'Origin not allowed' 
    });
  }

  // Log error
  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
    headers: {
      'user-agent': req.headers['user-agent'],
      'content-type': req.headers['content-type']
    }
  });

  // Determine status code
  const statusCode = err.status || err.statusCode || 500;

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { 
      stack: err.stack 
    }),
    ...(process.env.NODE_ENV === 'test' && { 
      testError: true 
    })
  });
});

// ================================
// SERVER CONFIGURATION
// ================================

const PORT = process.env.PORT || 3000;

// Only start server if this file is run directly
if (require.main === module) {
  app.listen(PORT, () => {
    logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
    logger.info(`Allowed CORS origins: ${allowedOrigins.join(', ')}`);
  });
}

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception', { error: err.message, stack: err.stack });
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', { reason, promise });
  process.exit(1);
});

module.exports = app;

/**
 * Security Test Suite for app.js
 * Run with: npm test
 */

const request = require('supertest');
const app = require('./app');

describe('Security Tests', () => {

  describe('Input Validation', () => {

    test('should reject invalid ID parameter', async () => {
      const response = await request(app)
        .get('/users?id=abc')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
      expect(response.body.details).toBeDefined();
    });

    test('should reject negative ID', async () => {
      const response = await request(app)
        .get('/users?id=-1')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject invalid email format', async () => {
      const response = await request(app)
        .get('/users?email=invalid-email')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject limit exceeding maximum', async () => {
      const response = await request(app)
        .get('/users?limit=101')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should reject negative offset', async () => {
      const response = await request(app)
        .get('/users?offset=-1')
        .expect(400);

      expect(response.body.error).toBe('Validation failed');
    });

    test('should sanitize XSS attempts in query params', async () => {
      const response = await request(app)
        .get('/users?email=<script>alert("xss")</script>@test.com')
        .expect(400);

      // Should be sanitized and fail validation
    });
  });

  describe('Error Handling', () => {

    test('should return 404 for non-existent routes', async () => {
      const response = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(response.body.error).toBe('Not Found');
      expect(response.body.path).toBe('/nonexistent');
    });

    test('should return 404 for non-existent user', async () => {
      const response = await request(app)
        .get('/users?id=999')
        .expect(404);

      expect(response.body.error).toBe('User not found');
    });

    test('should not expose stack traces in production mode', async () => {
      // In production mode (NODE_ENV=production)
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/nonexistent')
        .expect(404);

      expect(response.body.stack).toBeUndefined();

      process.env.NODE_ENV = originalEnv;
    });
  });

  describe('Security Headers', () => {

    test('should include security headers', async () => {
      const response = await request(app)
        .get('/health')
