const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const expressValidator = require('express-validator');
const morgan = require('morgan');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security headers via Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  frameguard: { action: 'deny' },
  xssFilter: true,
}));

// 2. Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: {
    error: 'Too many requests from this IP, please try again later.',
  },
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: {
    error: 'Too many login attempts, please try again later.',
  },
});

app.use(limiter);

// 3. Request body size limits to prevent DoS
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Logging with Morgan (rotate logs in production)
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined', {
    skip: (req, res) => {
      // Skip logging health checks to reduce noise
      return req.path === '/health';
    },
  }));
}

// 5. Input validation setup
const { param, query, validationResult } = expressValidator;

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
        value: err.value,
      })),
    });
  }
  next();
};

/**
 * Sanitize and validate email address
 */
const isValidEmail = (email) => {
  const emailRegex = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
  return emailRegex.test(email);
};

/**
 * Sanitize string input to prevent XSS
 */
const sanitizeString = (str) => {
  if (typeof str !== 'string') return str;
  return str.trim().replace(/[<>]/g, '');
};

/**
 * Validate and sanitize user ID parameter
 */
const validateUserId = [
  param('id')
    .notEmpty()
    .withMessage('User ID is required')
    .isInt({ min: 1, max: 999999 })
    .withMessage('User ID must be a positive integer')
    .toInt(),
  handleValidationErrors,
];

/**
 * Validate query parameters for users list
 */
const validateUsersQuery = [
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  handleValidationErrors,
];

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 */
const notFoundHandler = (req, res, next) => {
  res.status(404).json({
    error: 'Not Found',
    message: `Route ${req.method} ${req.path} not found`,
  });
};

/**
 * Global error handler
 * Always keeps stack traces out of production responses
 */
const errorHandler = (err, req, res, next) => {
  // Log the error (in production, use proper logging service)
  console.error('Error occurred:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    url: req.url,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send error response
  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' ? err.message : 'An error occurred',
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
};

/**
 * Async route wrapper to catch errors in async handlers
 */
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * Excluded from rate limiting in production for monitoring systems
 */
app.get('/health', (req, res) => {
  try {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
      environment: process.env.NODE_ENV || 'development',
    });
  } catch (error) {
    next(error);
  }
});

/**
 * Get users list with pagination
 * Includes input validation for query parameters
 */
app.get('/users', validateUsersQuery, asyncHandler(async (req, res) => {
  const limit = req.query.limit || 10;
  const offset = req.query.offset || 0;

  // Simulated database query
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply pagination
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    data: paginatedUsers,
    pagination: {
      limit,
      offset,
      total: users.length,
      hasMore: offset + limit < users.length,
    },
  });
}));

/**
 * Get single user by ID
 * Includes parameter validation
 */
app.get('/users/:id', validateUserId, asyncHandler(async (req, res) => {
  const userId = req.params.id;

  // Simulated database query
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === userId);

  if (!user) {
    const error = new Error('User not found');
    error.statusCode = 404;
    throw error;
  }

  res.json({ data: user });
}));

/**
 * Create new user (example of body validation)
 */
app.post(
  '/users',
  [
    // Validate request body
    expressValidator.body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 1, max: 100 })
      .withMessage('Name must be between 1 and 100 characters')
      .custom(sanitizeString),

    expressValidator.body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .custom((value) => {
        if (!isValidEmail(value)) {
          throw new Error('Email contains invalid characters');
        }
        return true;
      }),

    handleValidationErrors,
  ],
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    // Simulated user creation (in production, use database with parameterized queries)
    const newUser = {
      id: Date.now(), // In production, use proper ID generation
      name,
      email,
      createdAt: new Date().toISOString(),
    };

    // Log user creation for audit trail
    console.log('User created:', {
      id: newUser.id,
      email: newUser.email,
      ip: req.ip,
      timestamp: newUser.createdAt,
    });

    res.status(201).json({ data: newUser });
  })
);

// ============================================================================
// ERROR HANDLERS (must be last)
// ============================================================================

app.use(notFoundHandler);
app.use(errorHandler);

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

// Only start server if not running in test mode
if (require.main === module) {
  const server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
    console.log(`Health check: http://localhost:${PORT}/health`);
  });

  // Graceful shutdown handling
  const gracefulShutdown = (signal) => {
    console.log(`\n${signal} received. Starting graceful shutdown...`);

    server.close((err) => {
      if (err) {
        console.error('Error during server shutdown:', err);
        process.exit(1);
      }
      console.log('Server closed successfully');
      process.exit(0);
    });

    // Force shutdown after 10 seconds
    setTimeout(() => {
      console.error('Forced shutdown after timeout');
      process.exit(1);
    }, 10000);
  };

  process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
  process.on('SIGINT', () => gracefulShutdown('SIGINT'));

  // Handle uncaught exceptions
  process.on('uncaughtException', (err) => {
    console.error('Uncaught Exception:', err);
    gracefulShutdown('uncaughtException');
  });

  // Handle unhandled promise rejections
  process.on('unhandledRejection', (reason, promise) => {
    console.error('Unhandled Rejection at:', promise, 'reason:', reason);
    gracefulShutdown('unhandledRejection');
  });
}

module.exports = { app, server: app };

# Security Review of app.js

## Executive Summary

The original `app.js` is a minimal Express.js application that exposes endpoints for health checks and user data retrieval. While functional, it lacks **critical security controls**, **error handling**, and **input validation** that are essential for production applications.

---

## Critical Security Issues

### 🔴 High Severity

1. **No Input Validation**
   - All user inputs (params, query, body) are accepted without validation
   - No sanitization of special characters
   - Could lead to: SQL injection, NoSQL injection, XSS, command injection

2. **No Error Handling Middleware**
   - Unhandled exceptions will expose stack traces to users
   - No logging of errors for security monitoring
   - Poor user experience on errors

3. **Missing Security Headers**
   - No Content-Security-Policy (CSP)
   - No HTTP Strict Transport Security (HSTS)
   - No X-Content-Type-Options
   - No X-Frame-Options
   - Vulnerable to clickjacking, XSS, and MITM attacks

### 🟡 Medium Severity

4. **No Rate Limiting**
   - Vulnerable to brute force attacks
   - Susceptible to DoS/DDoS attacks
   - No protection against API abuse

5. **No Request Size Limits**
   - Large payloads can cause memory exhaustion
   - Potential for DoS via large request bodies

6. **No CORS Configuration**
   - Cross-origin requests not controlled
   - Could enable CSRF attacks

7. **No Logging/Auditing**
   - Security events not logged
   - No audit trail for compliance
   - Difficult to investigate incidents

---

## Detailed Recommendations

### 1. Input Validation Framework

**Current State:**
```javascript
app.get('/users/:id', (req, res) => {
  // No validation - any input accepted
});
```

**Recommended:**
```javascript
const { param, validationResult } = require('express-validator');

app.get('/users/:id', [
  param('id')
    .isInt({ min: 1, max: 999999 })
    .withMessage('ID must be a positive integer'),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Safe to proceed
});
```

### 2. Security Headers

**Add Helmet.js for security headers:**
```javascript
const helmet = require('helmet');

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));
```

### 3. Rate Limiting

**Implement using express-rate-limit:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
});

app.use(limiter);
```

### 4. Error Handling

**Create a global error handler:**
```javascript
const errorHandler = (err, req, res, next) => {
  // Log error for monitoring
  console.error('Error:', {
    message: err.message,
    url: req.url,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Don't expose stack traces in production
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: err.name || 'Internal Server Error',
    message: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'An error occurred',
  });
};

app.use(errorHandler);
```

### 5. Request Size Limits

**Configure body parser limits:**
```javascript
app.use(express.json({
  limit: '10kb', // Prevent large payload attacks
}));

app.use(express.urlencoded({
  limit: '10kb',
  extended: true,
}));
```

### 6. Async Error Handling

**Wrap async route handlers:**
```javascript
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

app.get('/users', asyncHandler(async (req, res) => {
  // Async errors will be caught
}));
```

### 7. Input Sanitization

**Sanitize user inputs:**
```javascript
const sanitizeString = (str) => {
  if (typeof str !== 'string') return str;
  return str.trim().replace(/[<>]/g, ''); // Remove < and >
};

// Use before processing user input
const safeName = sanitizeString(req.body.name);
```

---

## Additional Security Best Practices

### Environment Configuration

```javascript
// Never hardcode sensitive values
const config = {
  port: process.env.PORT || 3000,
  env: process.env.NODE_ENV || 'development',
  jwtSecret: process.env.JWT_SECRET,
  dbConnection: process.env.DATABASE_URL,
};
```

### Graceful Shutdown

```javascript
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});
```

### Security Logging

```javascript
// Log security-relevant events
const logSecurityEvent = (event, details) => {
  console.log(JSON.stringify({
    type: 'SECURITY_EVENT',
    event,
    details,
    timestamp: new Date().toISOString(),
  }));
};
```

---

## Required Dependencies

Add these to your `package.json`:

```json
{
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "express-rate-limit": "^6.7.0",
    "express-validator": "^7.0.1",
    "morgan": "^1.10.0"
  },
  "devDependencies": {
    "supertest": "^6.3.3",
    "jest": "^29.5.0"
  }
}
```

Install with:
```bash
npm install helmet express-rate-limit express-validator morgan
npm install --save-dev supertest jest
```

---

## Testing Recommendations

### 1. Input Validation Tests

```javascript
const request = require('supertest');
const app = require('./app');

describe('User Input Validation', () => {
  it('should reject invalid user ID', async () => {
    const res = await request(app)
      .get('/users/invalid')
      .expect(400);
  });

  it('should reject negative user ID', async () => {
    const res = await request(app)
      .get('/users/-1')
      .expect(400);
  });

  it('should reject oversized payloads', async () => {
    const largePayload = 'x'.repeat(20000);
    const res = await request(app)
      .post('/users')
      .send({ name: largePayload })
      .expect(413);
  });
});
```

### 2. Security Tests

```javascript
describe('Security Tests', () => {
  it('should have CSP header', async () => {
    const res = await request(app).get('/users');
    expect(res.headers['content-security-policy']).toBeDefined();
  });

  it('should have HSTS header', async () => {
    const res = await request(app).get('/users');
    expect(res.headers['strict-transport-security']).toBeDefined();
  });

  it('should rate limit requests', async () => {
    const promises = Array(150).fill(null).map(() => 
      request(app).get('/users')
    );
    const responses = await Promise.all(promises);
    const rateLimited = responses.filter(r => r.status === 429);
    expect(rateLimited.length).toBeGreaterThan(0);
  });
});
```

---

## Deployment Checklist

Before deploying to production:

- [ ] All security headers configured
- [ ] Rate limiting enabled for all endpoints
- [ ] Request size limits configured
- [ ] Input validation on all routes
- [ ] Error handling middleware configured
- [ ] Logging enabled for security events
- [ ] CORS properly configured
- [ ] HTTPS/TLS enabled
- [ ] Environment variables used for secrets
- [ ] Regular dependency updates (`npm audit`)
- [ ] Security scanning in CI/CD pipeline
- [ ] API documentation includes security considerations
- [ ] Monitoring and alerting configured

---

## OWASP Top 10 Coverage

| Risk | Mitigation in Improved Version |
|------|-------------------------------|
| A01: Broken Access Control | Input validation, proper error handling |
| A03: Injection | Input sanitization, parameter validation |
| A04: Insecure Design | Security headers, rate limiting |
| A05: Security Misconfiguration | Helmet.js, proper CORS |
| A07: ID and Auth Failures | Rate limiting, audit logging |
| A08: Software/Data Integrity | Dependency management, CSP |
| A09: Logging Failures | Morgan logger, security event logging |
| A10: Server-Side Request Forgery | Input validation, allowlist approach |

---

## Next Steps

1. **Review and implement** the improved `app-improved.js`
2. **Test thoroughly** using the provided test examples
3. **Set up monitoring** for security events
4. **Configure CI/CD** to include security scanning
5. **Document** API security guidelines for consumers
6. **Regular security audits** scheduled quarterly

---

## Resources

- [OWASP Node.js Security Cheat Sheet](https://cheatsheetseries.owasp.org/cheatsheets/Nodejs_Security_Cheat_Sheet.html)
- [Express Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Helmet.js Documentation](https://helmetjs.github.io/)
- [Express Validator Documentation](https://express-validator.github.io/)

