const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Rate limiting to prevent DDoS and brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Stricter rate limit for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10,
  message: 'Too many attempts, please try again later.',
});

// Body parsing with size limits
app.use(express.json({ 
  limit: '10kb',
  strict: true
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));

// ============================================================================
// VALIDATION MIDDLEWARE
// ============================================================================

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Log validation failures for security monitoring
    console.warn('Validation failed:', {
      ip: req.ip,
      path: req.path,
      errors: errors.array()
    });
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array()
    });
  }
  next();
};

// Sanitization and validation helpers
const validateId = (id) => {
  if (!id || typeof id !== 'string') {
    throw new Error('Invalid ID format');
  }
  // Allow only alphanumeric, hyphens, and underscores
  if (!/^[a-zA-Z0-9_-]+$/.test(id)) {
    throw new Error('ID contains invalid characters');
  }
  // Length check
  if (id.length > 50) {
    throw new Error('ID exceeds maximum length');
  }
  return id;
};

const validateEmail = (email) => {
  if (!email || typeof email !== 'string') {
    throw new Error('Invalid email format');
  }
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    throw new Error('Invalid email format');
  }
  // Length check
  if (email.length > 254) {
    throw new Error('Email exceeds maximum length');
  }
  return email.toLowerCase().trim();
};

// ============================================================================
// SECURITY UTILITIES
// ============================================================================

// Security logger
const securityLogger = (req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logData = {
      timestamp: new Date().toISOString(),
      ip: req.ip,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      userAgent: req.get('user-agent')
    };

    // Log suspicious activity
    if (res.statusCode >= 400) {
      console.warn('Request failed:', logData);
    } else {
      console.log('Request completed:', logData);
    }
  });

  next();
};

app.use(securityLogger);

// ============================================================================
// MOCK DATA (In production, use a proper database with parameterized queries)
// ============================================================================

const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

// 404 handler - must be after all routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found',
    path: req.path
  });
});

// Global error handler - must be last
app.use((err, req, res, next) => {
  // Log error for debugging and security monitoring
  console.error('Error occurred:', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    ip: req.ip,
    path: req.path,
    method: req.method
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Send sanitized error response
  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime()
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Get users with optional filtering and validation
app.get('/users', [
  // Validate and sanitize query parameters
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('sort').optional().isIn(['name', 'email', 'id']),
  query('order').optional().isIn(['asc', 'desc']),
  query('email')
    .optional()
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
], handleValidationErrors, (req, res, next) => {
  try {
    // Extract validated query parameters
    const { page = 1, limit = 10, sort = 'id', order = 'asc', email } = req.query;

    let filteredUsers = [...users];

    // Apply email filter if provided
    if (email) {
      try {
        const validatedEmail = validateEmail(email);
        filteredUsers = filteredUsers.filter(u => 
          u.email.toLowerCase() === validatedEmail
        );
      } catch (err) {
        return res.status(400).json({ error: err.message });
      }
    }

    // Apply sorting
    filteredUsers.sort((a, b) => {
      const aVal = a[sort];
      const bVal = b[sort];
      const comparison = aVal < bVal ? -1 : aVal > bVal ? 1 : 0;
      return order === 'desc' ? -comparison : comparison;
    });

    // Apply pagination
    const startIndex = (page - 1) * limit;
    const endIndex = startIndex + limit;
    const paginatedUsers = filteredUsers.slice(startIndex, endIndex);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total: filteredUsers.length,
        totalPages: Math.ceil(filteredUsers.length / limit)
      }
    });
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Get a single user by ID with validation
app.get('/users/:id', [
  // Note: In express-validator, we'd use param() validation
], handleValidationErrors, (req, res, next) => {
  try {
    // Validate and sanitize the ID parameter
    const id = parseInt(req.params.id, 10);

    if (isNaN(id)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'ID must be a valid integer'
      });
    }

    if (id < 1 || id > 2147483647) {
      return res.status(400).json({
        error: 'Invalid user ID',
        message: 'ID is out of valid range'
      });
    }

    // Find user
    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        error: 'Not Found',
        message: `User with ID ${id} not found`
      });
    }

    res.json(user);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Example of a POST endpoint with full validation
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 1, max: 100 }).withMessage('Name must be between 1 and 100 characters')
    .matches(/^[a-zA-Z\s'-]+$/).withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .notEmpty().withMessage('Email is required')
    .isEmail().withMessage('Invalid email format')
    .normalizeEmail()
    .isLength({ max: 254 }).withMessage('Email exceeds maximum length'),
], handleValidationErrors, (req, res, next) => {
  try {
    const { name, email } = req.body;

    // Additional validation
    const validatedEmail = validateEmail(email);

    // Check for duplicate email (in production, use database unique constraint)
    const emailExists = users.some(u => u.email.toLowerCase() === validatedEmail);
    if (emailExists) {
      return res.status(409).json({
        error: 'Conflict',
        message: 'A user with this email already exists'
      });
    }

    // Create user (in production, save to database with parameterized query)
    const newUser = {
      id: users.length + 1,
      name: name.trim(),
      email: validatedEmail
    };

    users.push(newUser);

    // Log user creation for audit
    console.info('User created:', {
      userId: newUser.id,
      email: newUser.email,
      ip: req.ip,
      timestamp: new Date().toISOString()
    });

    res.status(201).json(newUser);
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  // Force close after 10 seconds
  setTimeout(() => {
    console.error('Forcing server shutdown after timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  gracefulShutdown('uncaughtException');
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  gracefulShutdown('unhandledRejection');
});

module.exports = app;

# Security Improvements for app.js

## Executive Summary

This document outlines critical security vulnerabilities found in the original `app.js` and provides detailed recommendations for implementing robust error handling and input validation following security best practices.

---

## Critical Security Vulnerabilities Found

### 1. **Lack of Input Validation** ⚠️ CRITICAL
**Issue:** No validation of any user inputs (query parameters, route parameters, headers)

**Risks:**
- SQL/NoSQL injection attacks
- Path traversal attacks  
- XSS attacks
- DoS via malformed inputs
- Data corruption

**Impact:** HIGH - Could lead to data breaches, system compromise, or denial of service

---

### 2. **No Error Handling** ⚠️ CRITICAL
**Issue:** Missing try-catch blocks and global error handling middleware

**Risks:**
- Sensitive information leakage in stack traces
- Application crashes
- Inconsistent error responses
- No audit trail for security incidents

**Impact:** HIGH - Information disclosure and availability issues

---

### 3. **Missing Security Headers** ⚠️ HIGH
**Issue:** No implementation of security headers (CSP, HSTS, X-Frame-Options, etc.)

**Risks:**
- Clickjacking attacks
- XSS attacks
- MITM attacks
- Content injection

**Impact:** HIGH - Multiple attack vectors enabled

---

### 4. **No Rate Limiting** ⚠️ HIGH
**Issue:** Unlimited requests allowed from any IP

**Risks:**
- DDoS attacks
- Brute force attacks
- API abuse
- Resource exhaustion

**Impact:** HIGH - Availability and security issues

---

### 5. **No Request Size Limits** ⚠️ MEDIUM
**Issue:** Unlimited body size in requests

**Risks:**
- Memory exhaustion
- DoS via large payloads
- Server crashes

**Impact:** MEDIUM - Availability impact

---

### 6. **Missing Logging** ⚠️ MEDIUM
**Issue:** No request/error logging for security monitoring

**Risks:**
- No incident detection
- No forensic evidence
- No compliance with security standards

**Impact:** MEDIUM - Detection and response capabilities compromised

---

## Detailed Improvements

### 1. Security Headers (Helmet.js)

```javascript
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", "data:"],
    }
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));
```

**Benefits:**
- Prevents XSS via Content-Security-Policy
- Prevents clickjacking via X-Frame-Options
- Enforces HTTPS via HSTS
- Disables MIME-type sniffing via X-Content-Type-Options
- Prevents referrer leakage via Referrer-Policy

---

### 2. Rate Limiting

```javascript
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);
```

**Benefits:**
- Prevents DDoS attacks
- Limits brute force attempts
- Protects against API abuse
- Configurable per-sensitivity (strictLimiter for sensitive endpoints)

---

### 3. Request Size Limits

```javascript
app.use(express.json({ 
  limit: '10kb',
  strict: true
}));
app.use(express.urlencoded({ 
  extended: true, 
  limit: '10kb' 
}));
```

**Benefits:**
- Prevents memory exhaustion
- Blocks large payload attacks
- Reduces attack surface

---

### 4. Input Validation withexpress-validator

```javascript
app.get('/users', [
  query('email')
    .optional()
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
], handleValidationErrors, handler);
```

**Benefits:**
- Type enforcement
- Length constraints
- Format validation
- Input sanitization
- Consistent error messages

---

### 5. Custom Validation Functions

```javascript
const validateId = (id) => {
  if (!id || typeof id !== 'string') {
    throw new Error('Invalid ID format');
  }
  if (!/^[a-zA-Z0-9_-]+$/.test(id)) {
    throw new Error('ID contains invalid characters');
  }
  if (id.length > 50) {
    throw new Error('ID exceeds maximum length');
  }
  return id;
};
```

**Benefits:**
- Prevents injection attacks
- Enforces business rules
- Centralized validation logic
- Reusable across endpoints

---

### 6. Global Error Handling

```javascript
app.use((err, req, res, next) => {
  console.error('Error occurred:', {
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    ip: req.ip,
    path: req.path,
    method: req.method
  });

  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: statusCode === 500 ? 'Internal Server Error' : err.message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack })
  });
});
```

**Benefits:**
- Centralized error handling
- Prevents information leakage (no stack traces in production)
- Consistent error responses
- Comprehensive error logging

---

### 7. Security Logging

```javascript
const securityLogger = (req, res, next) => {
  const startTime = Date.now();

  res.on('finish', () => {
    const logData = {
      timestamp: new Date().toISOString(),
      ip: req.ip,
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${Date.now() - startTime}ms`,
      userAgent: req.get('user-agent')
    };

    if (res.statusCode >= 400) {
      console.warn('Request failed:', logData);
    } else {
      console.log('Request completed:', logData);
    }
  });

  next();
};
```

**Benefits:**
- Security monitoring
- Incident detection
- Forensic evidence
- Compliance support

---

### 8. Graceful Shutdown

```javascript
const gracefulShutdown = (signal) => {
  console.log(`${signal} received. Starting graceful shutdown...`);

  server.close(() => {
    console.log('Server closed successfully');
    process.exit(0);
  });

  setTimeout(() => {
