// Improved application with security best practices
// Includes error handling, input validation, and security headers

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult, matchedData } = require('express-validator');
const morgan = require('morgan');

const app = express();

// Security middleware
app.use(helmet()); // Security headers
app.use(express.json({ limit: '10kb' })); // Request body size limit
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Logging middleware
app.use(morgan('combined'));

// Rate limiting to prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again after 15 minutes',
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter rate limiting for sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 requests per 15 minutes for sensitive endpoints
  message: 'Too many attempts, please try again later',
});

app.use(limiter);

// Centralized error handler
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Validation error handler
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      success: false,
      errors: errors.array().map(err => ({
        field: err.path || err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// Sanitize and validate user input
const sanitizeInput = (input) => {
  if (typeof input !== 'string') return input;
  return input
    .trim()
    .replace(/[<>]/g, '') // Remove potential HTML tags
    .substring(0, 1000); // Limit length
};

// Generic error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', {
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
    ip: req.ip,
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'An unexpected error occurred' 
    : err.message;

  res.status(statusCode).json({
    success: false,
    error: message,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    success: false,
    error: 'Endpoint not found',
  });
});

// Health check endpoint with rate limiting exemption
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      uptime: process.uptime(),
    });
  } catch (error) {
    res.status(500).json({ success: false, error: 'Health check failed' });
  }
});

// Get users with input validation
app.get('/users', 
  [
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .withMessage('Limit must be between 1 and 100')
      .toInt(),
    query('offset')
      .optional()
      .isInt({ min: 0 })
      .withMessage('Offset must be a non-negative integer')
      .toInt(),
    query('sort')
      .optional()
      .isIn(['id', 'name', 'email'])
      .withMessage('Invalid sort field'),
    query('order')
      .optional()
      .isIn(['asc', 'desc'])
      .withMessage('Order must be asc or desc'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const validatedData = matchedData(req);

    // Mock users data
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    // Apply pagination
    const limit = validatedData.limit || 10;
    const offset = validatedData.offset || 0;
    let users = allUsers.slice(offset, offset + limit);

    // Apply sorting
    if (validatedData.sort) {
      users.sort((a, b) => {
        const aVal = a[validatedData.sort].toLowerCase();
        const bVal = b[validatedData.sort].toLowerCase();
        const multiplier = validatedData.order === 'desc' ? -1 : 1;
        return aVal.localeCompare(bVal) * multiplier;
      });
    }

    res.json({
      success: true,
      data: users,
      pagination: {
        limit,
        offset,
        total: allUsers.length,
      },
    });
  })
);

// Get single user by ID with validation
app.get('/users/:id',
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { id } = req.params;

    // Mock users data
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
      { id: 3, name: 'Charlie', email: 'charlie@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found',
      });
    }

    res.json({
      success: true,
      data: user,
    });
  })
);

// Create user endpoint with validation (POST)
app.post('/users',
  strictLimiter,
  [
    body('name')
      .trim()
      .notEmpty()
      .withMessage('Name is required')
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .trim()
      .notEmpty()
      .withMessage('Email is required')
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail()
      .isLength({ max: 100 })
      .withMessage('Email is too long'),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const validatedData = matchedData(req);

    // Sanitize inputs
    const sanitizedData = {
      name: sanitizeInput(validatedData.name),
      email: sanitizeInput(validatedData.email),
    };

    // In a real application, you would save to database here
    // const newUser = await User.create(sanitizedData);

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: {
        id: Date.now(), // Mock ID
        ...sanitizedData,
      },
    });
  })
);

// Update user endpoint with validation (PUT)
app.put('/users/:id',
  strictLimiter,
  [
    param('id')
      .isInt({ min: 1 })
      .withMessage('User ID must be a positive integer')
      .toInt(),
    body('name')
      .optional()
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('Name must be between 2 and 50 characters')
      .matches(/^[a-zA-Z\s'-]+$/)
      .withMessage('Name contains invalid characters'),
    body('email')
      .optional()
      .trim()
      .isEmail()
      .withMessage('Invalid email format')
      .normalizeEmail(),
  ],
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { id } = req.params;
    const validatedData = matchedData(req);

    // Check if user exists
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    const user = users.find(u => u.id === id);

    if (!user) {
      return res.status(404).json({
        success: false,
        error: 'User not found',
      });
    }

    // Sanitize inputs
    const sanitizedData = {};
    if (validatedData.name) sanitizedData.name = sanitizeInput(validatedData.name);
    if (validatedData.email) sanitizedData.email = sanitizeInput(validatedData.email);

    res.json({
      success: true,
      message: 'User updated successfully',
      data: {
        id,
        ...user,
        ...sanitizedData,
      },
    });
  })
);

// Start server only if not importing for testing
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
    console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
  });
}

module.exports = app;

# Security Improvements for app.js

## Executive Summary

The original `app.js` lacked critical security measures, error handling, and input validation. This document outlines the improvements made and provides additional security recommendations.

